1	//! Neural→VSA Bridge: project LLM hidden states into hypervector space.
2	//!
3	//! Maps LLM hidden states (f32 tensors of dimension `hidden_dim`, e.g. 1536
4	//! for Qwen2.5-1.5B) to 10K-bit bipolar HyperVecs via a learned linear
5	//! projection + binarization.
6	//!
7	//! **Encoding pipeline**:
8	//! 1. Extract hidden state `h` from LLM layer (f32, `[hidden_dim]`)
9	//! 2. Project: `z = W·h + b` where W is `[vsa_dim, hidden_dim]`
10	//! 3. Binarize: `v[i] = 1 if z[i] > 0 else 0` (bipolar: 1 → +1, 0 → -1)
11	//! 4. Result: 10K-bit HyperVec compatible with all VSA operations
12	//!
13	//! **Training**: Self-supervised alignment against grounded VSA vectors in
14	//! ItemMemory. CPU-feasible (~15M f32 params for 1.5B model).
15	//!
16	//! **What this enables**:
17	//! - Concept identification via ItemMemory nearest-neighbor search
18	//! - Quality gate: if encoded vector is far from all known concepts, LLM may
19	//!   be hallucinating
20	//! - Interpretability: which KG concepts activate when processing text?
21	
22	use super::{Dimension, Encoding, HyperVec};
23	
24	// ---------------------------------------------------------------------------
25	// Linear projection
26	// ---------------------------------------------------------------------------
27	
28	/// A simple linear projection `y = W·x + b`.
29	///
30	/// Stored as flat f32 arrays for simplicity and compatibility with safetensors.
31	#[derive(Debug, Clone)]
32	pub struct LinearProjection {
33	    /// Weight matrix, row-major: `[out_dim × in_dim]`.
34	    weight: Vec<f32>,
35	    /// Bias vector: `[out_dim]`.
36	    bias: Vec<f32>,
37	    /// Input dimension.
38	    in_dim: usize,
39	    /// Output dimension.
40	    out_dim: usize,
41	}
42	
43	impl LinearProjection {
44	    /// Create a new projection with the given dimensions.
45	    ///
46	    /// Weights are initialized to small random values (Xavier uniform).
47	    pub fn new(in_dim: usize, out_dim: usize) -> Self {
48	        use rand::Rng;
49	        let mut rng = rand::thread_rng();
50	        let limit = (6.0 / (in_dim + out_dim) as f32).sqrt();
51	
52	        let weight: Vec<f32> = (0..out_dim * in_dim)
53	            .map(|_| rng.gen_range(-limit..limit))
54	            .collect();
55	        let bias = vec![0.0f32; out_dim];
56	
57	        Self {
58	            weight,
59	            bias,
60	            in_dim,
61	            out_dim,
62	        }
63	    }
64	
65	    /// Create a projection with pre-loaded weights.
66	    pub fn from_weights(weight: Vec<f32>, bias: Vec<f32>, in_dim: usize, out_dim: usize) -> Self {
67	        debug_assert_eq!(weight.len(), out_dim * in_dim);
68	        debug_assert_eq!(bias.len(), out_dim);
69	        Self {
70	            weight,
71	            bias,
72	            in_dim,
73	            out_dim,
74	        }
75	    }
76	
77	    /// Forward pass: `y = W·x + b`.
78	    pub fn forward(&self, input: &[f32]) -> Vec<f32> {
79	        debug_assert_eq!(input.len(), self.in_dim);
80	        let mut output = self.bias.clone();
81	        for row in 0..self.out_dim {
82	            let row_start = row * self.in_dim;
83	            let mut dot = 0.0f32;
84	            for col in 0..self.in_dim {
85	                dot += self.weight[row_start + col] * input[col];
86	            }
87	            output[row] += dot;
88	        }
89	        output
90	    }
91	
92	    /// Access weights (for serialization).
93	    pub fn weight(&self) -> &[f32] {
94	        &self.weight
95	    }
96	
97	    /// Access bias (for serialization).
98	    pub fn bias(&self) -> &[f32] {
99	        &self.bias
100	    }

