1	//! Skill manager: discover, warm, activate, and deactivate skillpacks.
2	//!
3	//! Scans a skills directory for subdirectories containing `skill.json` manifests.
4	//! Each skill follows the lifecycle: Cold → Warm → Hot.
5	
6	use std::collections::HashMap;
7	use std::path::PathBuf;
8	use std::sync::RwLock;
9	use std::sync::atomic::{AtomicUsize, Ordering};
10	
11	use egg::{Pattern, Rewrite};
12	
13	use crate::error::{SkillError, SkillResult};
14	use crate::graph::Triple;
15	use crate::graph::index::KnowledgeGraph;
16	use crate::reason::AkhLang;
17	use crate::symbol::SymbolId;
18	
19	use super::{LoadedSkill, SkillActivation, SkillInfo, SkillManifest, SkillState};
20	
21	/// Manages the lifecycle of skillpacks.
22	pub struct SkillManager {
23	    skills_dir: PathBuf,
24	    skills: RwLock<HashMap<String, LoadedSkill>>,
25	    loaded_bytes: AtomicUsize,
26	    max_bytes: usize,
27	    /// Stored rule text per skill: skill_id -> Vec<(name, lhs, rhs)>.
28	    #[allow(clippy::type_complexity)]
29	    rule_sources: RwLock<HashMap<String, Vec<(String, String, String)>>>,
30	}
31	
32	impl std::fmt::Debug for SkillManager {
33	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
34	        f.debug_struct("SkillManager")
35	            .field("skills_dir", &self.skills_dir)
36	            .field("loaded_bytes", &self.loaded_bytes.load(Ordering::Relaxed))
37	            .field("max_bytes", &self.max_bytes)
38	            .finish()
39	    }
40	}
41	
42	impl SkillManager {
43	    /// Create a new skill manager.
44	    ///
45	    /// `max_memory_mb` is the total memory budget for loaded skillpacks.
46	    pub fn new(skills_dir: PathBuf, max_memory_mb: usize) -> Self {
47	        Self {
48	            skills_dir,
49	            skills: RwLock::new(HashMap::new()),
50	            loaded_bytes: AtomicUsize::new(0),
51	            max_bytes: max_memory_mb * 1024 * 1024,
52	            rule_sources: RwLock::new(HashMap::new()),
53	        }
54	    }
55	
56	    /// Get the skills directory path.
57	    pub fn skills_dir(&self) -> &std::path::Path {
58	        &self.skills_dir
59	    }
60	
61	    /// Scan the skills directory for subdirectories containing `skill.json`.
62	    ///
63	    /// Registers each found skill as Cold. Returns the number of skills discovered.
64	    pub fn discover(&self) -> SkillResult<usize> {
65	        if !self.skills_dir.exists() {
66	            return Err(SkillError::NoSkillsDir {
67	                path: self.skills_dir.display().to_string(),
68	            });
69	        }
70	
71	        let entries = std::fs::read_dir(&self.skills_dir).map_err(|e| SkillError::Io {
72	            skill_id: "<discovery>".into(),
73	            source: e,
74	        })?;
75	
76	        let mut count = 0;
77	        let mut skills = self.skills.write().expect("skills lock poisoned");
78	
79	        for entry in entries {
80	            let entry = entry.map_err(|e| SkillError::Io {
81	                skill_id: "<discovery>".into(),
82	                source: e,
83	            })?;
84	            let path = entry.path();
85	            if !path.is_dir() {
86	                continue;
87	            }
88	
89	            let manifest_path = path.join("skill.json");
90	            if !manifest_path.exists() {
91	                continue;
92	            }
93	
94	            // Use the directory name as the skill ID for discovery.
95	            let skill_id = path
96	                .file_name()
97	                .and_then(|n| n.to_str())
98	                .unwrap_or("unknown")
99	                .to_string();
100	
101	            if !skills.contains_key(&skill_id) {
102	                skills.insert(
103	                    skill_id.clone(),
104	                    LoadedSkill {
105	                        manifest: SkillManifest {
106	                            id: skill_id,
107	                            name: String::new(),
108	                            version: String::new(),
109	                            description: String::new(),
110	                            domains: Vec::new(),
111	                            weight_size_bytes: 0,
112	                            triples_file: None,
113	                            rules_file: None,
114	                            cli_tools: Vec::new(),
115	                            wasm_tools: Vec::new(),
116	                            tool_config: std::collections::HashMap::new(),
117	                        },
118	                        state: SkillState::Cold,
119	                        triple_count: 0,
120	                        rule_count: 0,
121	                        memory_bytes: 0,
122	                    },
123	                );
124	                count += 1;
125	            }
126	        }
127	
128	        Ok(count)
129	    }
130	
131	    /// Parse the manifest for a Cold skill, transitioning it to Warm.
132	    pub fn warm(&self, skill_id: &str) -> SkillResult<SkillManifest> {
133	        let mut skills = self.skills.write().expect("skills lock poisoned");
134	        let skill = skills
135	            .get_mut(skill_id)
136	            .ok_or_else(|| SkillError::NotFound {
137	                name: skill_id.into(),
138	            })?;
139	
140	        if skill.state != SkillState::Cold {
141	            return Err(SkillError::InvalidTransition {
142	                skill_id: skill_id.into(),
143	                from: skill.state.to_string(),
144	                to: "Warm".into(),
145	            });
146	        }
147	
148	        let manifest_path = self.skills_dir.join(skill_id).join("skill.json");
149	        let content = std::fs::read_to_string(&manifest_path).map_err(|e| SkillError::Io {
150	            skill_id: skill_id.into(),
151	            source: e,
152	        })?;
153	
154	        let manifest: SkillManifest =
155	            serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
156	                path: manifest_path.display().to_string(),
157	                message: e.to_string(),
158	            })?;
159	
160	        skill.manifest = manifest.clone();
161	        skill.state = SkillState::Warm;
162	
163	        Ok(manifest)
164	    }
165	
166	    /// Activate a Warm skill: load triples into the knowledge graph
167	    /// and parse rules. Transitions the skill to Hot.
168	    pub fn activate(
169	        &self,
170	        skill_id: &str,
171	        knowledge_graph: &KnowledgeGraph,
172	    ) -> SkillResult<SkillActivation> {
173	        let mut skills = self.skills.write().expect("skills lock poisoned");
174	        let skill = skills
175	            .get_mut(skill_id)
176	            .ok_or_else(|| SkillError::NotFound {
177	                name: skill_id.into(),
178	            })?;
179	
180	        if skill.state != SkillState::Warm {
181	            return Err(SkillError::InvalidTransition {
182	                skill_id: skill_id.into(),
183	                from: skill.state.to_string(),
184	                to: "Hot".into(),
185	            });
186	        }
187	
188	        let skill_dir = self.skills_dir.join(skill_id);
189	        let mut triples_loaded = 0usize;
190	        let mut rules_loaded = 0usize;
191	        let mut memory_estimate = 0usize;
192	
193	        // Load triples if available.
194	        let triples_file = skill
195	            .manifest
196	            .triples_file
197	            .clone()
198	            .unwrap_or_else(|| "triples.json".into());
199	        let triples_path = skill_dir.join(&triples_file);
200	        if triples_path.exists() {
201	            let content = std::fs::read_to_string(&triples_path).map_err(|e| SkillError::Io {
202	                skill_id: skill_id.into(),
203	                source: e,
204	            })?;
205	
206	            let raw_triples: Vec<serde_json::Value> =
207	                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
208	                    path: triples_path.display().to_string(),
209	                    message: format!("triples parse error: {e}"),
210	                })?;
211	
212	            for val in &raw_triples {
213	                let s = val["s"].as_u64().unwrap_or(0);
214	                let p = val["p"].as_u64().unwrap_or(0);
215	                let o = val["o"].as_u64().unwrap_or(0);
216	
217	                if let (Some(s), Some(p), Some(o)) =
218	                    (SymbolId::new(s), SymbolId::new(p), SymbolId::new(o))
219	                {
220	                    // Ignore duplicate triple errors.
221	                    let _ = knowledge_graph.insert_triple(&Triple::new(s, p, o));
222	                    triples_loaded += 1;
223	                }
224	            }
225	
226	            memory_estimate += content.len();
227	        }
228	
229	        // Load rules if available.
230	        let rules_file = skill
231	            .manifest
232	            .rules_file
233	            .clone()
234	            .unwrap_or_else(|| "rules.txt".into());
235	        let rules_path = skill_dir.join(&rules_file);
236	        let mut rule_tuples: Vec<(String, String, String)> = Vec::new();
237	        if rules_path.exists() {
238	            let content = std::fs::read_to_string(&rules_path).map_err(|e| SkillError::Io {
239	                skill_id: skill_id.into(),
240	                source: e,
241	            })?;
242	
243	            for (i, line) in content.lines().enumerate() {
244	                let line = line.trim();
245	                if line.is_empty() || line.starts_with('#') {
246	                    continue;
247	                }
248	                if let Some((lhs, rhs)) = line.split_once("=>") {
249	                    let name = format!("{}-rule-{}", skill_id, i);
250	                    rule_tuples.push((name, lhs.trim().to_string(), rhs.trim().to_string()));
251	                    rules_loaded += 1;
252	                } else {
253	                    return Err(SkillError::InvalidRule {
254	                        skill_id: skill_id.into(),
255	                        message: format!("line {}: missing '=>' separator", i + 1),
256	                    });
257	                }
258	            }
259	
260	            memory_estimate += content.len();
261	        }
262	
263	        // Check memory budget.
264	        let current = self.loaded_bytes.load(Ordering::Relaxed);
265	        if current + memory_estimate > self.max_bytes {
266	            return Err(SkillError::MemoryBudgetExceeded {
267	                required_mb: memory_estimate / (1024 * 1024) + 1,
268	                available_mb: (self.max_bytes.saturating_sub(current)) / (1024 * 1024),
269	            });
270	        }
271	
272	        // Commit.
273	        self.loaded_bytes
274	            .fetch_add(memory_estimate, Ordering::Relaxed);
275	        skill.state = SkillState::Hot;
276	        skill.triple_count = triples_loaded;
277	        skill.rule_count = rules_loaded;
278	        skill.memory_bytes = memory_estimate;
279	
280	        if !rule_tuples.is_empty() {
281	            self.rule_sources
282	                .write()
283	                .expect("rule_sources lock poisoned")
284	                .insert(skill_id.to_string(), rule_tuples);
285	        }
286	
287	        Ok(SkillActivation {
288	            skill_id: skill_id.into(),
289	            triples_loaded,
290	            rules_loaded,
291	            memory_bytes: memory_estimate,
292	        })
293	    }
294	
295	    /// Deactivate a Hot skill: mark inactive, free budget.
296	    /// Triples already in the KG persist until engine restart.
297	    pub fn deactivate(&self, skill_id: &str) -> SkillResult<()> {
298	        let mut skills = self.skills.write().expect("skills lock poisoned");
299	        let skill = skills
300	            .get_mut(skill_id)
301	            .ok_or_else(|| SkillError::NotFound {
302	                name: skill_id.into(),
303	            })?;
304	
305	        if skill.state != SkillState::Hot {
306	            return Err(SkillError::InvalidTransition {
307	                skill_id: skill_id.into(),
308	                from: skill.state.to_string(),
309	                to: "Warm (deactivate)".into(),
310	            });
311	        }
312	
313	        self.loaded_bytes
314	            .fetch_sub(skill.memory_bytes, Ordering::Relaxed);
315	        skill.state = SkillState::Warm;
316	        skill.memory_bytes = 0;
317	
318	        self.rule_sources
319	            .write()
320	            .expect("rule_sources lock poisoned")
321	            .remove(skill_id);
322	
323	        Ok(())
324	    }
325	
326	    /// Get the current state of a skill, or `None` if not discovered.
327	    pub fn skill_state(&self, skill_id: &str) -> Option<SkillState> {
328	        let skills = self.skills.read().expect("skills lock poisoned");
329	        skills.get(skill_id).map(|s| s.state)
330	    }
331	
332	    /// Build an activation summary for an already-Hot skill (idempotent reload).
333	    pub fn hot_activation(&self, skill_id: &str) -> Option<SkillActivation> {
334	        let skills = self.skills.read().expect("skills lock poisoned");
335	        let skill = skills.get(skill_id)?;
336	        if skill.state != SkillState::Hot {
337	            return None;
338	        }
339	        Some(SkillActivation {
340	            skill_id: skill_id.to_string(),
341	            triples_loaded: skill.triple_count,
342	            rules_loaded: skill.rule_count,
343	            memory_bytes: skill.memory_bytes,
344	        })
345	    }
346	
347	    /// Add extra triples to a Hot skill's count (e.g. label triples loaded externally).
348	    pub fn add_triple_count(&self, skill_id: &str, extra: usize) {
349	        let mut skills = self.skills.write().expect("skills lock poisoned");
350	        if let Some(skill) = skills.get_mut(skill_id) {
351	            skill.triple_count += extra;
352	        }
353	    }
354	
355	    /// List all known skills with their current state.
356	    pub fn list(&self) -> Vec<SkillInfo> {
357	        let skills = self.skills.read().expect("skills lock poisoned");
358	        skills
359	            .values()
360	            .map(|s| SkillInfo {
361	                id: s.manifest.id.clone(),
362	                name: s.manifest.name.clone(),
363	                version: s.manifest.version.clone(),
364	                description: s.manifest.description.clone(),
365	                state: s.state,
366	                domains: s.manifest.domains.clone(),
367	                triple_count: s.triple_count,
368	                rule_count: s.rule_count,
369	            })
370	            .collect()
371	    }
372	
373	    /// Build rewrite rules from all active (Hot) skills.
374	    pub fn active_rules(&self) -> Vec<Rewrite<AkhLang, ()>> {
375	        let rule_sources = self
376	            .rule_sources
377	            .read()
378	            .expect("rule_sources lock poisoned");
379	        let mut rules = Vec::new();
380	
381	        for (skill_id, tuples) in rule_sources.iter() {
382	            for (name, lhs, rhs) in tuples {
383	                // egg::rewrite! is a macro; we must use the lower-level API.
384	                let lhs_result: Result<Pattern<AkhLang>, _> = lhs.parse();
385	                let rhs_result: Result<Pattern<AkhLang>, _> = rhs.parse();
386	                if let (Ok(lhs_pat), Ok(rhs_pat)) = (lhs_result, rhs_result) {
387	                    match Rewrite::new(name.clone(), lhs_pat, rhs_pat) {
388	                        Ok(rule) => rules.push(rule),
389	                        Err(e) => {
390	                            tracing::warn!(
391	                                skill_id,
392	                                rule = name.as_str(),
393	                                error = %e,
394	                                "failed to compile skill rule, skipping"
395	                            );
396	                        }
397	                    }
398	                } else {
399	                    tracing::warn!(
400	                        skill_id,
401	                        rule = name.as_str(),
402	                        "failed to parse skill rule patterns, skipping"
403	                    );
404	                }
405	            }
406	        }
407	
408	        rules
409	    }
410	
411	    /// Get info for a specific skill.
412	    pub fn get_info(&self, skill_id: &str) -> SkillResult<SkillInfo> {
413	        let skills = self.skills.read().expect("skills lock poisoned");
414	        let skill = skills.get(skill_id).ok_or_else(|| SkillError::NotFound {
415	            name: skill_id.into(),
416	        })?;
417	        Ok(SkillInfo {
418	            id: skill.manifest.id.clone(),
419	            name: skill.manifest.name.clone(),
420	            version: skill.manifest.version.clone(),
421	            description: skill.manifest.description.clone(),
422	            state: skill.state,
423	            domains: skill.manifest.domains.clone(),
424	            triple_count: skill.triple_count,
425	            rule_count: skill.rule_count,
426	        })
427	    }
428	}
429	
430	#[cfg(test)]
431	mod tests {
432	    use super::*;
433	    use tempfile::TempDir;
434	
435	    /// Create a temp skills directory with a test skillpack.
436	    fn setup_skill_dir() -> (TempDir, PathBuf) {
437	        let dir = TempDir::new().unwrap();
438	        let skills_dir = dir.path().join("skills");
439	        std::fs::create_dir(&skills_dir).unwrap();
440	
441	        let skill_dir = skills_dir.join("astronomy");
442	        std::fs::create_dir(&skill_dir).unwrap();
443	
444	        // Write manifest.
445	        let manifest = serde_json::json!({
446	            "id": "astronomy",
447	            "name": "Astronomy Pack",
448	            "version": "1.0.0",
449	            "description": "Basic astronomical knowledge",
450	            "domains": ["astronomy", "science"],
451	            "weight_size_bytes": 0,
452	            "triples_file": "triples.json",
453	            "rules_file": "rules.txt"
454	        });
455	        std::fs::write(
456	            skill_dir.join("skill.json"),
457	            serde_json::to_string_pretty(&manifest).unwrap(),
458	        )
459	        .unwrap();
460	
461	        // Write triples.
462	        let triples = serde_json::json!([
463	            {"s": 1, "p": 2, "o": 3},
464	            {"s": 3, "p": 2, "o": 4}
465	        ]);
466	        std::fs::write(
467	            skill_dir.join("triples.json"),
468	            serde_json::to_string(&triples).unwrap(),
469	        )
470	        .unwrap();
471	
472	        // Write rules.
473	        std::fs::write(
474	            skill_dir.join("rules.txt"),
475	            "# Astronomy rules\n(similar ?x ?y) => (similar ?y ?x)\n",
476	        )
477	        .unwrap();
478	
479	        (dir, skills_dir)
480	    }
481	
482	    #[test]
483	    fn discover_skills() {
484	        let (_dir, skills_dir) = setup_skill_dir();
485	        let mgr = SkillManager::new(skills_dir, 100);
486	        let count = mgr.discover().unwrap();
487	        assert_eq!(count, 1);
488	
489	        let list = mgr.list();
490	        assert_eq!(list.len(), 1);
491	        assert_eq!(list[0].id, "astronomy");
492	        assert_eq!(list[0].state, SkillState::Cold);
493	    }
494	
495	    #[test]
496	    fn warm_parses_manifest() {
497	        let (_dir, skills_dir) = setup_skill_dir();
498	        let mgr = SkillManager::new(skills_dir, 100);
499	        mgr.discover().unwrap();
500	
501	        let manifest = mgr.warm("astronomy").unwrap();
502	        assert_eq!(manifest.name, "Astronomy Pack");
503	        assert_eq!(manifest.version, "1.0.0");
504	        assert_eq!(manifest.domains, vec!["astronomy", "science"]);
505	    }
506	
507	    #[test]
508	    fn activate_loads_triples() {
509	        let (_dir, skills_dir) = setup_skill_dir();
510	        let mgr = SkillManager::new(skills_dir, 100);
511	        let kg = KnowledgeGraph::new();
512	
513	        mgr.discover().unwrap();
514	        mgr.warm("astronomy").unwrap();
515	        let activation = mgr.activate("astronomy", &kg).unwrap();
516	
517	        assert_eq!(activation.triples_loaded, 2);
518	        assert!(kg.triple_count() >= 2);
519	    }
520	
521	    #[test]
522	    fn activate_loads_rules() {
523	        let (_dir, skills_dir) = setup_skill_dir();
524	        let mgr = SkillManager::new(skills_dir, 100);
525	        let kg = KnowledgeGraph::new();
526	
527	        mgr.discover().unwrap();
528	        mgr.warm("astronomy").unwrap();
529	        let activation = mgr.activate("astronomy", &kg).unwrap();
530	        assert_eq!(activation.rules_loaded, 1);
531	
532	        let rules = mgr.active_rules();
533	        assert_eq!(rules.len(), 1);
534	    }
535	
536	    #[test]
537	    fn budget_enforcement() {
538	        let (_dir, skills_dir) = setup_skill_dir();
539	        // Extremely small budget: 0 MB.
540	        let mgr = SkillManager::new(skills_dir, 0);
541	        let kg = KnowledgeGraph::new();
542	
543	        mgr.discover().unwrap();
544	        mgr.warm("astronomy").unwrap();
545	        let result = mgr.activate("astronomy", &kg);
546	        assert!(matches!(
547	            result,
548	            Err(SkillError::MemoryBudgetExceeded { .. })
549	        ));
550	    }
551	
552	    #[test]
553	    fn deactivate_frees_budget() {
554	        let (_dir, skills_dir) = setup_skill_dir();
555	        let mgr = SkillManager::new(skills_dir, 100);
556	        let kg = KnowledgeGraph::new();
557	
558	        mgr.discover().unwrap();
559	        mgr.warm("astronomy").unwrap();
560	        let activation = mgr.activate("astronomy", &kg).unwrap();
561	        assert!(activation.memory_bytes > 0);
562	
563	        mgr.deactivate("astronomy").unwrap();
564	
565	        let info = mgr.get_info("astronomy").unwrap();
566	        assert_eq!(info.state, SkillState::Warm);
567	
568	        // Rules should be cleared.
569	        let rules = mgr.active_rules();
570	        assert!(rules.is_empty());
571	    }
