1	//! Item Memory: symbol-to-hypervector mapping with ANN search.
2	//!
3	//! The item memory is the central registry of all symbol hypervectors.
4	//! It provides:
5	//! - Lazy allocation: `get_or_create(symbol)` generates a deterministic vector on first access
6	//! - Fast ANN search: find the most similar symbols to a query vector
7	//! - Concurrent access via DashMap for the symbol registry
8	
9	use std::sync::RwLock;
10	
11	use anndists::dist::DistHamming;
12	use dashmap::DashMap;
13	use hnsw_rs::hnsw::Hnsw;
14	
15	use crate::error::VsaError;
16	use crate::symbol::SymbolId;
17	
18	use super::encode::encode_symbol;
19	use super::ops::{VsaOps, VsaResult};
20	use super::{Dimension, Encoding, HyperVec};
21	
22	/// Search result from item memory.
23	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
24	pub struct SearchResult {
25	    /// The matching symbol ID.
26	    pub symbol_id: SymbolId,
27	    /// Similarity score (0.0 = unrelated, 1.0 = identical).
28	    pub similarity: f32,
29	}
30	
31	/// Item Memory: the registry of all symbol hypervectors.
32	///
33	/// Combines a concurrent hashmap for exact lookups with an HNSW index
34	/// for approximate nearest-neighbor search.
35	pub struct ItemMemory {
36	    /// Exact symbol → hypervector mapping.
37	    vectors: DashMap<SymbolId, HyperVec>,
38	    /// HNSW ANN index for similarity search.
39	    /// Uses u32 data with Hamming distance for bipolar vectors.
40	    hnsw: RwLock<Hnsw<'static, u32, DistHamming>>,
41	    /// Mapping from HNSW internal IDs to SymbolIds.
42	    id_to_symbol: DashMap<usize, SymbolId>,
43	    /// Next HNSW internal ID to assign.
44	    next_hnsw_id: std::sync::atomic::AtomicUsize,
45	    /// Dimension and encoding config.
46	    dim: Dimension,
47	    encoding: Encoding,
48	}
49	
50	// Safety: Hnsw uses internal synchronization via atomics/locks.
51	// The RwLock wrapper provides the outer synchronization needed.
52	unsafe impl Send for ItemMemory {}
53	unsafe impl Sync for ItemMemory {}
54	
55	impl ItemMemory {
56	    /// Create a new empty item memory.
57	    ///
58	    /// `max_elements` is a capacity hint for the HNSW index.
59	    pub fn new(dim: Dimension, encoding: Encoding, max_elements: usize) -> Self {
60	        // HNSW parameters:
61	        // max_nb_connection: 16 (standard for moderate dimensions)
62	        // ef_construction: 200 (higher = better recall during build)
63	        // max_layer: computed from expected elements
64	        let max_layer = (max_elements as f64).log2().ceil() as usize;
65	        let max_layer = max_layer.clamp(4, 16);
66	
67	        let hnsw = Hnsw::new(max_layer, max_elements, 16, 200, DistHamming {});
68	
69	        Self {
70	            vectors: DashMap::new(),
71	            hnsw: RwLock::new(hnsw),
72	            id_to_symbol: DashMap::new(),
73	            next_hnsw_id: std::sync::atomic::AtomicUsize::new(0),
74	            dim,
75	            encoding,
76	        }
77	    }
78	
79	    /// Get the hypervector for a symbol, creating it if it doesn't exist.
80	    ///
81	    /// The vector is deterministically derived from the symbol ID,
82	    /// so this is idempotent.
83	    pub fn get_or_create(&self, ops: &VsaOps, symbol: SymbolId) -> HyperVec {
84	        if let Some(entry) = self.vectors.get(&symbol) {
85	            return entry.value().clone();
86	        }
87	
88	        let vec = encode_symbol(ops, symbol);
89	        self.insert(symbol, vec.clone());
90	        vec
91	    }
92	
93	    /// Insert a specific hypervector for a symbol.
94	    pub fn insert(&self, symbol: SymbolId, vec: HyperVec) {
95	        // Convert to u32 slices for HNSW (bit-packed representation)
96	        let data_u32 = bytes_to_u32_vec(vec.data());
97	        let hnsw_id = self
98	            .next_hnsw_id
99	            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
100	
101	        // Insert into HNSW — insert takes &self, not &mut self
102	        if let Ok(hnsw) = self.hnsw.read() {
103	            hnsw.insert((&data_u32, hnsw_id));
104	        }
105	
