pub fn bind(&self, a: &HyperVec, b: &HyperVec) -> VsaResult<HyperVec> {
    check_compatible(a, b)?;
    let mut out = vec![0u8; a.byte_len()];
    self.kernel.xor_bind(a.data(), b.data(), &mut out);
