/// Read a skill's manifest JSON from its directory.
fn read_skill_manifest(
    skill_dir: &std::path::Path,
) -> Result<crate::skills::SkillManifest, String> {
    let manifest_path = skill_dir.join("skill.json");
    let json =
        std::fs::read_to_string(&manifest_path).map_err(|e| format!("read skill.json: {e}"))?;
    serde_json::from_str(&json).map_err(|e| format!("parse skill.json: {e}"))
}

/// Create a new agent wrapping the given engine.
///
/// Initializes well-known predicates, registers built-in tools, and
/// optionally restores goals from the KG.
pub fn new(engine: Arc<Engine>, config: AgentConfig) -> AgentResult<Self> {
    let predicates = AgentPredicates::init(&engine)?;
    let project_predicates = ProjectPredicates::init(&engine)?;
    let dialogue_predicates = super::dialogue::DialoguePredicates::init(&engine)?;

    // Write skill.json template.
    let manifest = serde_json::json!({
        "id": name,
        "name": name,
        "version": "0.1.0",
        "description": format!("{name} knowledge domain"),
        "domains": [&name],
        "weight_size_bytes": 0,
        "triples_file": "triples.json",
        "rules_file": "rules.txt"
    });
    std::fs::write(
        skill_dir.join("skill.json"),
        serde_json::to_string_pretty(&manifest).into_diagnostic()?,
    )
    .into_diagnostic()?;

    // Write example triples.json in label-based format.
    let triples = serde_json::json!([
        {
            "subject": "ExampleEntity",
            "predicate": "is-a",
            "object": "Category",
            "confidence": 1.0
        }
    ]);
    std::fs::write(
        skill_dir.join("triples.json"),
        serde_json::to_string_pretty(&triples).into_diagnostic()?,
    )
    .into_diagnostic()?;

    // Write rules.txt template.
    std::fs::write(
        skill_dir.join("rules.txt"),
        "# Rewrite rules for this skillpack.\n\
         # Format: <lhs-pattern> => <rhs-pattern>\n\
         # Example:\n\
         # (similar ?x ?y) => (similar ?y ?x)\n",
    )
    .into_diagnostic()?;

    println!("Scaffolded skill '{}' at {}", name, skill_dir.display());
    println!("  skill.json   - manifest (edit name, domains, description)");
    println!("  triples.json - knowledge triples (label-based format)");
    println!("  rules.txt    - rewrite rules");
}

