1	//! Skill manager: discover, warm, activate, and deactivate skillpacks.
2	//!
3	//! Scans a skills directory for subdirectories containing `skill.json` manifests.
4	//! Each skill follows the lifecycle: Cold → Warm → Hot.
5	//!
6	//! Extended in Phase 31:
7	//! - 31a: dependency-graph-aware activation (via `graph.rs`)
8	//! - 31b: per-skill neural prototype storage and query matching
9	//! - 31c: last-used tracking for idle-deactivation routing
10	
11	use std::collections::HashMap;
12	use std::path::PathBuf;
13	use std::sync::RwLock;
14	use std::sync::atomic::{AtomicUsize, Ordering};
15	use std::time::{Duration, Instant};
16	
17	use dashmap::DashMap;
18	use egg::{Pattern, Rewrite};
19	
20	use crate::error::{SkillError, SkillResult};
21	use crate::graph::Triple;
22	use crate::graph::index::KnowledgeGraph;
23	use crate::reason::AkhLang;
24	use crate::symbol::SymbolId;
25	use crate::vsa::HyperVec;
26	use crate::vsa::encode::encode_symbol;
27	use crate::vsa::ops::VsaOps;
28	
29	use super::{LoadedSkill, SkillActivation, SkillInfo, SkillManifest, SkillState};
30	
31	/// Manages the lifecycle of skillpacks.
32	pub struct SkillManager {
33	    skills_dir: PathBuf,
34	    skills: RwLock<HashMap<String, LoadedSkill>>,
35	    loaded_bytes: AtomicUsize,
36	    max_bytes: usize,
37	    /// Stored rule text per skill: skill_id -> Vec<(name, lhs, rhs)>.
38	    #[allow(clippy::type_complexity)]
39	    rule_sources: RwLock<HashMap<String, Vec<(String, String, String)>>>,
40	    /// Triples loaded from each active skill (skill_id → triples).
41	    /// Used by Phase 31b prototype computation.
42	    skill_triples: RwLock<HashMap<String, Vec<Triple>>>,
43	    /// Neural prototype per skill (skill_id → serialised HyperVec bytes).
44	    /// Populated at activation time via `compute_and_store_prototype`.
45	    prototypes: DashMap<String, Vec<u8>>,
46	    /// Last-access timestamp per Hot skill (Phase 31c idle-deactivation).
47	    last_used: DashMap<String, Instant>,
48	}
49	
50	impl std::fmt::Debug for SkillManager {
51	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
52	        f.debug_struct("SkillManager")
53	            .field("skills_dir", &self.skills_dir)
54	            .field("loaded_bytes", &self.loaded_bytes.load(Ordering::Relaxed))
55	            .field("max_bytes", &self.max_bytes)
56	            .finish()
57	    }
58	}
59	
60	impl SkillManager {
61	    /// Create a new skill manager.
62	    ///
63	    /// `max_memory_mb` is the total memory budget for loaded skillpacks.
64	    pub fn new(skills_dir: PathBuf, max_memory_mb: usize) -> Self {
65	        Self {
66	            skills_dir,
67	            skills: RwLock::new(HashMap::new()),
