82	    /// Scan the skills directory for subdirectories containing `skill.json`.
83	    ///
84	    /// Registers each found skill as Cold. Returns the number of skills discovered.
85	    pub fn discover(&self) -> SkillResult<usize> {
86	        if !self.skills_dir.exists() {
87	            return Err(SkillError::NoSkillsDir {
88	                path: self.skills_dir.display().to_string(),
89	            });
90	        }
91	
92	        let entries = std::fs::read_dir(&self.skills_dir).map_err(|e| SkillError::Io {
93	            skill_id: "<discovery>".into(),
94	            source: e,
95	        })?;
96	
97	        let mut count = 0;
98	        let mut skills = self.skills.write().expect("skills lock poisoned");
99	
100	        for entry in entries {
101	            let entry = entry.map_err(|e| SkillError::Io {
102	                skill_id: "<discovery>".into(),
103	                source: e,
104	            })?;
105	            let path = entry.path();
106	            if !path.is_dir() {
107	                continue;
108	            }
109	
110	            let manifest_path = path.join("skill.json");
111	            if !manifest_path.exists() {
112	                continue;
113	            }
114	
115	            // Use the directory name as the skill ID for discovery.
116	            let skill_id = path
117	                .file_name()
118	                .and_then(|n| n.to_str())
119	                .unwrap_or("unknown")
120	                .to_string();
121	
122	            if !skills.contains_key(&skill_id) {
123	                skills.insert(
124	                    skill_id.clone(),
125	                    LoadedSkill {
126	                        manifest: SkillManifest {
127	                            id: skill_id,
128	                            name: String::new(),
129	                            version: String::new(),
130	                            description: String::new(),
131	                            domains: Vec::new(),
132	                            weight_size_bytes: 0,
133	                            triples_file: None,
134	                            rules_file: None,
135	                            cli_tools: Vec::new(),
136	                            wasm_tools: Vec::new(),
137	                            tool_config: std::collections::HashMap::new(),
138	                            depends: Vec::new(),
139	                            conflicts: Vec::new(),
140	                            provides: Vec::new(),
141	                            requires: Vec::new(),
142	                            remote_url: None,
143	                            curriculum_file: None,
144	                        },
145	                        state: SkillState::Cold,
146	                        triple_count: 0,
147	                        rule_count: 0,
148	                        memory_bytes: 0,
149	                        last_used_at: None,
150	                    },
151	                );
152	                count += 1;
153	            }
154	        }
155	
156	        Ok(count)
157	    }
