194	    /// Activate a Warm skill: load triples into the knowledge graph
195	    /// and parse rules. Transitions the skill to Hot.
196	    ///
197	    /// Phase 31a: checks for conflicts with currently active skills before
198	    /// loading. Phase 31c: records the activation timestamp.
199	    pub fn activate(
200	        &self,
201	        skill_id: &str,
202	        knowledge_graph: &KnowledgeGraph,
203	    ) -> SkillResult<SkillActivation> {
204	        // Phase 31a: conflict check against currently active skills.
205	        let active_ids = self.active_skill_ids();
206	        {
207	            let skills = self.skills.read().expect("skills lock poisoned");
208	            if let Some(skill) = skills.get(skill_id) {
209	                if let Some(conflict) = super::graph::SkillDependencyGraph::check_conflicts(
210	                    &skill.manifest,
211	                    &active_ids,
212	                ) {
213	                    return Err(SkillError::SkillConflict {
214	                        skill_id: skill_id.into(),
215	                        conflict,
216	                    });
217	                }
218	            }
219	        }
220	
221	        let mut skills = self.skills.write().expect("skills lock poisoned");
222	        let skill = skills
223	            .get_mut(skill_id)
224	            .ok_or_else(|| SkillError::NotFound {
225	                name: skill_id.into(),
226	            })?;
227	
228	        if skill.state != SkillState::Warm {
229	            return Err(SkillError::InvalidTransition {
230	                skill_id: skill_id.into(),
231	                from: skill.state.to_string(),
232	                to: "Hot".into(),
233	            });
234	        }
235	
236	        let skill_dir = self.skills_dir.join(skill_id);
237	        let mut triples_loaded = 0usize;
238	        let mut rules_loaded = 0usize;
239	        let mut memory_estimate = 0usize;
240	        let mut loaded_triples: Vec<Triple> = Vec::new();
241	
242	        // Load triples if available.
243	        let triples_file = skill
244	            .manifest
245	            .triples_file
246	            .clone()
247	            .unwrap_or_else(|| "triples.json".into());
248	        let triples_path = skill_dir.join(&triples_file);
249	        if triples_path.exists() {
250	            let content = std::fs::read_to_string(&triples_path).map_err(|e| SkillError::Io {
251	                skill_id: skill_id.into(),
252	                source: e,
253	            })?;
254	
255	            let raw_triples: Vec<serde_json::Value> =
256	                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
257	                    path: triples_path.display().to_string(),
258	                    message: format!("triples parse error: {e}"),
259	                })?;
260	
261	            for val in &raw_triples {
262	                let s = val["s"].as_u64().unwrap_or(0);
263	                let p = val["p"].as_u64().unwrap_or(0);
264	                let o = val["o"].as_u64().unwrap_or(0);
265	
266	                if let (Some(s), Some(p), Some(o)) =
267	                    (SymbolId::new(s), SymbolId::new(p), SymbolId::new(o))
268	                {
269	                    let triple = Triple::new(s, p, o);
270	                    // Ignore duplicate triple errors.
271	                    let _ = knowledge_graph.insert_triple(&triple);
272	                    loaded_triples.push(triple);
273	                    triples_loaded += 1;
274	                }
275	            }
276	
277	            memory_estimate += content.len();
278	        }
279	
280	        // Load rules if available.
281	        let rules_file = skill
282	            .manifest
283	            .rules_file
284	            .clone()
285	            .unwrap_or_else(|| "rules.txt".into());
286	        let rules_path = skill_dir.join(&rules_file);
287	        let mut rule_tuples: Vec<(String, String, String)> = Vec::new();
288	        if rules_path.exists() {
289	            let content = std::fs::read_to_string(&rules_path).map_err(|e| SkillError::Io {
290	                skill_id: skill_id.into(),
291	                source: e,
292	            })?;
293	
294	            for (i, line) in content.lines().enumerate() {
295	                let line = line.trim();
296	                if line.is_empty() || line.starts_with('#') {
297	                    continue;
298	                }
299	                if let Some((lhs, rhs)) = line.split_once("=>") {
300	                    let name = format!("{}-rule-{}", skill_id, i);
301	                    rule_tuples.push((name, lhs.trim().to_string(), rhs.trim().to_string()));
302	                    rules_loaded += 1;
303	                } else {
304	                    return Err(SkillError::InvalidRule {
305	                        skill_id: skill_id.into(),
306	                        message: format!("line {}: missing '=>' separator", i + 1),
307	                    });
308	                }
309	            }
310	
311	            memory_estimate += content.len();
312	        }
313	
314	        // Check memory budget.
315	        let current = self.loaded_bytes.load(Ordering::Relaxed);
316	        if current + memory_estimate > self.max_bytes {
317	            return Err(SkillError::MemoryBudgetExceeded {
318	                required_mb: memory_estimate / (1024 * 1024) + 1,
319	                available_mb: (self.max_bytes.saturating_sub(current)) / (1024 * 1024),
320	            });
321	        }
322	
323	        // Commit.
324	        self.loaded_bytes
325	            .fetch_add(memory_estimate, Ordering::Relaxed);
326	        skill.state = SkillState::Hot;
327	        skill.triple_count = triples_loaded;
328	        skill.rule_count = rules_loaded;
329	        skill.memory_bytes = memory_estimate;
330	        // Phase 31c: record activation time.
331	        skill.last_used_at = Some(Instant::now());
332	
333	        if !rule_tuples.is_empty() {
334	            self.rule_sources
335	                .write()
336	                .expect("rule_sources lock poisoned")
337	                .insert(skill_id.to_string(), rule_tuples);
338	        }
339	
340	        // Phase 31b: store triples for prototype computation.
341	        if !loaded_triples.is_empty() {
342	            self.skill_triples
343	                .write()
344	                .expect("skill_triples lock poisoned")
345	                .insert(skill_id.to_string(), loaded_triples);
346	        }
347	
348	        // Phase 31c: record last-used timestamp.
349	        self.last_used.insert(skill_id.to_string(), Instant::now());
350	
351	        Ok(SkillActivation {
352	            skill_id: skill_id.into(),
353	            triples_loaded,
354	            rules_loaded,
355	            memory_bytes: memory_estimate,
356	        })
357	    }
