448	    /// Build rewrite rules from all active (Hot) skills.
449	    pub fn active_rules(&self) -> Vec<Rewrite<AkhLang, ()>> {
450	        let rule_sources = self
451	            .rule_sources
452	            .read()
453	            .expect("rule_sources lock poisoned");
454	        let mut rules = Vec::new();
455	
456	        for (skill_id, tuples) in rule_sources.iter() {
457	            for (name, lhs, rhs) in tuples {
458	                // egg::rewrite! is a macro; we must use the lower-level API.
459	                let lhs_result: Result<Pattern<AkhLang>, _> = lhs.parse();
460	                let rhs_result: Result<Pattern<AkhLang>, _> = rhs.parse();
461	                if let (Ok(lhs_pat), Ok(rhs_pat)) = (lhs_result, rhs_result) {
462	                    match Rewrite::new(name.clone(), lhs_pat, rhs_pat) {
463	                        Ok(rule) => rules.push(rule),
464	                        Err(e) => {
465	                            tracing::warn!(
466	                                skill_id,
467	                                rule = name.as_str(),
468	                                error = %e,
469	                                "failed to compile skill rule, skipping"
470	                            );
471	                        }
472	                    }
473	                } else {
474	                    tracing::warn!(
475	                        skill_id,
476	                        rule = name.as_str(),
477	                        "failed to parse skill rule patterns, skipping"
478	                    );
479	                }
480	            }
481	        }
482	
483	        rules
484	    }
