1	//! Cross-skill inference: bridge rules for overlapping skill concepts.
2	//!
3	//! Phase 31g — when two skills are co-active and share overlapping concepts
4	//! (detected via neural prototype similarity), bridge rules are generated to
5	//! disambiguate polysemy or integrate complementary knowledge.
6	//!
7	//! Bridge rules are egg rewrite-rule strings tagged with multi-skill
8	//! provenance so reasoning chains that cross skill boundaries record which
9	//! skills contributed.
10	
11	use serde::{Deserialize, Serialize};
12	
13	use crate::symbol::SymbolId;
14	
15	/// A bridge rule connecting concepts from two co-active skills.
16	///
17	/// Bridge rules are expressed in egg's rewrite syntax (same format as the
18	/// `rules.txt` file) and are generated when overlapping concepts are detected.
19	#[derive(Debug, Clone, Serialize, Deserialize)]
20	pub struct BridgeRule {
21	    /// Name of the rule (unique within the manager).
22	    pub name: String,
23	    /// Egg rewrite LHS pattern (e.g. `"(is_a ?x star)"`).
24	    pub lhs: String,
25	    /// Egg rewrite RHS pattern (e.g. `"(ambiguous ?x star)"`).
26	    pub rhs: String,
27	    /// Skill IDs whose overlap motivated this rule.
28	    pub source_skills: [String; 2],
29	    /// Human-readable explanation of what this bridge handles.
30	    pub rationale: String,
31	}
32	
33	/// Provenance tag for inferences that used bridge rules.
34	#[derive(Debug, Clone, Serialize, Deserialize)]
35	pub struct BridgeProvenance {
36	    /// Skills whose bridge rule was applied.
37	    pub source_skills: Vec<String>,
38	    /// Rule name that fired.
39	    pub rule_name: String,
40	}
41	
42	/// Detected overlap between two co-active skills.
43	#[derive(Debug, Clone, Serialize, Deserialize)]
44	pub struct SkillOverlap {
45	    /// First skill ID.
46	    pub skill_a: String,
47	    /// Second skill ID.
48	    pub skill_b: String,
49	    /// Prototype similarity score (0.0–1.0).
50	    pub similarity: f32,
51	    /// Symbol IDs present in both skills' triple sets.
52	    pub shared_symbols: Vec<SymbolId>,
53	}
54	
55	/// Threshold above which two skill prototypes are considered overlapping.
56	pub const OVERLAP_THRESHOLD: f32 = 0.55;
57	
58	/// Detect overlaps between all pairs of active skills.
59	///
60	/// `skill_ids` is the list of currently-active skill IDs.
61	/// `prototype_similarity` is a callback that returns the similarity between
62	/// two skills' prototype vectors (provided by the caller using Phase 31b data).
63	///
64	/// Returns only pairs where similarity exceeds `OVERLAP_THRESHOLD`.
65	pub fn detect_overlaps<F>(skill_ids: &[String], mut prototype_similarity: F) -> Vec<SkillOverlap>
66	where
67	    F: FnMut(&str, &str) -> Option<(f32, Vec<SymbolId>)>,
68	{
69	    let mut overlaps = Vec::new();
70	    for (i, a) in skill_ids.iter().enumerate() {
71	        for b in skill_ids.iter().skip(i + 1) {
72	            if let Some((sim, shared)) = prototype_similarity(a, b) {
73	                if sim > OVERLAP_THRESHOLD {
74	                    overlaps.push(SkillOverlap {
75	                        skill_a: a.clone(),
76	                        skill_b: b.clone(),
77	                        similarity: sim,
78	                        shared_symbols: shared,
79	                    });
80	                }
81	            }
82	        }
83	    }
84	    overlaps
85	}
86	
87	/// Generate a disambiguation bridge rule for a shared polysemous symbol.
88	///
89	/// When `symbol_label` appears in both skill A and skill B with conflicting
90	/// predicate contexts, the bridge rule flags it as ambiguous:
91	/// `(is_a ?x <label>) => (ambiguous ?x <label>)`.
92	pub fn generate_disambiguation_rule(
93	    overlap: &SkillOverlap,
94	    symbol_label: &str,
95	    rule_index: usize,
96	) -> BridgeRule {
97	    BridgeRule {
98	        name: format!(
99	            "bridge-{}-{}-disambig-{}",
100	            overlap.skill_a, overlap.skill_b, rule_index
101	        ),
102	        lhs: format!("(is_a ?x {symbol_label})"),
103	        rhs: format!("(ambiguous ?x {symbol_label})"),
104	        source_skills: [overlap.skill_a.clone(), overlap.skill_b.clone()],
105	        rationale: format!(
106	            "Symbol '{symbol_label}' appears in both '{}' and '{}' with potentially \
107	             different meanings; flagged as ambiguous.",
108	            overlap.skill_a, overlap.skill_b
109	        ),
110	    }
111	}
112	
113	/// Generate an integration bridge rule for a complementary shared symbol.
114	///
115	/// When `symbol_label` represents the same concept in both skills and the
116	/// skills' knowledge is complementary, the rule propagates facts:
117	/// `(concept_in_a ?x) => (concept_in_b ?x)`.
118	pub fn generate_integration_rule(
119	    overlap: &SkillOverlap,
120	    symbol_label: &str,
121	    predicate_a: &str,
122	    predicate_b: &str,
123	    rule_index: usize,
124	) -> BridgeRule {
125	    BridgeRule {
126	        name: format!(
127	            "bridge-{}-{}-integrate-{}",
128	            overlap.skill_a, overlap.skill_b, rule_index
129	        ),
130	        lhs: format!("({predicate_a} ?x {symbol_label})"),
131	        rhs: format!("({predicate_b} ?x {symbol_label})"),
132	        source_skills: [overlap.skill_a.clone(), overlap.skill_b.clone()],
133	        rationale: format!(
134	            "Bridges '{predicate_a}' from '{}' with '{predicate_b}' from '{}' \
135	             via shared concept '{symbol_label}'.",
136	            overlap.skill_a, overlap.skill_b
137	        ),
138	    }
139	}
140	
141	/// Summarise a set of bridge rules as a string block suitable for inclusion
142	/// in a `rules.txt` file.
143	pub fn rules_to_text(rules: &[BridgeRule]) -> String {
144	    let mut out = String::new();
145	    for rule in rules {
146	        out.push_str(&format!("# {}\n", rule.rationale));
147	        out.push_str(&format!("{} => {}\n", rule.lhs, rule.rhs));
148	    }
149	    out
150	}
