1	//! Skill curriculum: learning progression for bootstrapping.
2	//!
3	//! Phase 31h — extends skills with a Bloom-taxonomy-based curriculum that
4	//! orders concept acquisition, specifies mastery targets, and provides
5	//! assessment queries. The bootstrap pipeline (Phase 14) uses curricula to
6	//! structure domain learning.
7	
8	use serde::{Deserialize, Serialize};
9	
10	use crate::error::{SkillError, SkillResult};
11	
12	/// Bloom's taxonomy mastery target for a curriculum concept.
13	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
14	pub enum BloomLevel {
15	    /// Recall facts and basic concepts.
16	    Remember,
17	    /// Explain ideas or concepts.
18	    Understand,
19	    /// Use information in new situations.
20	    Apply,
21	    /// Draw connections among ideas.
22	    Analyze,
23	    /// Justify a decision or course of action.
24	    Evaluate,
25	    /// Produce new or original work.
26	    Create,
27	}
28	
29	impl std::fmt::Display for BloomLevel {
30	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
31	        let s = match self {
32	            Self::Remember => "remember",
33	            Self::Understand => "understand",
34	            Self::Apply => "apply",
35	            Self::Analyze => "analyze",
36	            Self::Evaluate => "evaluate",
37	            Self::Create => "create",
38	        };
39	        write!(f, "{s}")
40	    }
41	}
42	
43	impl std::str::FromStr for BloomLevel {
44	    type Err = String;
45	    fn from_str(s: &str) -> Result<Self, Self::Err> {
46	        match s.to_lowercase().as_str() {
47	            "remember" => Ok(Self::Remember),
48	            "understand" => Ok(Self::Understand),
49	            "apply" => Ok(Self::Apply),
50	            "analyze" | "analyse" => Ok(Self::Analyze),
51	            "evaluate" => Ok(Self::Evaluate),
52	            "create" => Ok(Self::Create),
53	            other => Err(format!("unknown Bloom level: {other}")),
54	        }
55	    }
56	}
57	
58	/// A single concept within a skill's curriculum.
59	#[derive(Debug, Clone, Serialize, Deserialize)]
60	pub struct CurriculumConcept {
61	    /// The concept's label (maps to a symbol in the KG).
62	    pub name: String,
63	    /// Target mastery level for this concept.
64	    pub bloom_target: BloomLevel,
65	    /// Concept IDs that must be understood before this one.
66	    #[serde(default)]
67	    pub prerequisites: Vec<String>,
68	}
69	
70	/// An assessment query for testing understanding of a skill's concepts.
71	#[derive(Debug, Clone, Serialize, Deserialize)]
72	pub struct Assessment {
73	    /// The question or reasoning task (natural language).
74	    pub query: String,
75	    /// Concept names the correct answer should reference.
76	    pub expected_concepts: Vec<String>,
77	    /// The Bloom level this assessment targets.
78	    pub bloom_level: BloomLevel,
79	}
80	
81	/// A learning progression for a skillpack.
82	///
83	/// Curricula are stored in `curriculum.json` alongside `skill.json` and
84	/// are loaded on demand.
85	#[derive(Debug, Clone, Serialize, Deserialize)]
86	pub struct SkillCurriculum {
87	    /// All concepts covered by the skill.
88	    pub concepts: Vec<CurriculumConcept>,
89	    /// Topological layers: each inner `Vec` contains concept names that can be
90	    /// learned in parallel once the previous layer is complete.
91	    #[serde(default)]
92	    pub layers: Vec<Vec<String>>,
93	    /// Assessment queries ordered from foundational to advanced.
94	    #[serde(default)]
95	    pub assessments: Vec<Assessment>,
96	}
97	
98	impl SkillCurriculum {
99	    /// Load a curriculum from a JSON file.
100	    pub fn load(path: &std::path::Path) -> SkillResult<Self> {
101	        let content = std::fs::read_to_string(path).map_err(|e| SkillError::Io {
102	            skill_id: path.display().to_string(),
103	            source: e,
104	        })?;
105	        serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
106	            path: path.display().to_string(),
107	            message: format!("curriculum parse error: {e}"),
108	        })
109	    }
110	
111	    /// Compute topological layers from concept prerequisites using a simple
112	    /// Kahn's algorithm.
113	    ///
114	    /// Returns layers ordered from "learn first" to last. Concepts not
115	    /// reachable in the prerequisite graph appear in the final layer.
116	    pub fn compute_layers(&self) -> Vec<Vec<String>> {
117	        use std::collections::{HashMap, HashSet, VecDeque};
118	
119	        let concept_names: HashSet<&str> = self.concepts.iter().map(|c| c.name.as_str()).collect();
120	
121	        // in-degree: number of prerequisites still unsatisfied
122	        let mut in_degree: HashMap<&str, usize> = HashMap::new();
123	        let mut dependents: HashMap<&str, Vec<&str>> = HashMap::new();
124	
125	        for c in &self.concepts {
126	            let entry = in_degree.entry(c.name.as_str()).or_insert(0);
127	            for pre in &c.prerequisites {
128	                if concept_names.contains(pre.as_str()) {
129	                    *entry += 1;
130	                    dependents
131	                        .entry(pre.as_str())
132	                        .or_default()
133	                        .push(c.name.as_str());
134	                }
135	            }
136	        }
137	
138	        let mut queue: VecDeque<&str> = in_degree
139	            .iter()
140	            .filter(|(_, &d)| d == 0)
141	            .map(|(&name, _)| name)
142	            .collect();
143	
144	        let mut layers: Vec<Vec<String>> = Vec::new();
145	
146	        while !queue.is_empty() {
147	            let layer_size = queue.len();
148	            let mut layer: Vec<String> = Vec::with_capacity(layer_size);
149	            for _ in 0..layer_size {
150	                let name = queue.pop_front().unwrap();
151	                layer.push(name.to_string());
152	                if let Some(deps) = dependents.get(name) {
153	                    for &dep in deps {
154	                        let d = in_degree.get_mut(dep).unwrap();
155	                        *d -= 1;
156	                        if *d == 0 {
157	                            queue.push_back(dep);
158	                        }
159	                    }
160	                }
161	            }
162	            layers.push(layer);
163	        }
164	
165	        layers
166	    }
167	
168	    /// Return all concepts at or below the given Bloom level that have no
169	    /// unsatisfied prerequisites (given a set of already-mastered concepts).
170	    pub fn next_concepts<'a>(
171	        &'a self,
172	        mastered: &std::collections::HashSet<String>,
173	        max_level: BloomLevel,
174	    ) -> Vec<&'a CurriculumConcept> {
175	        self.concepts
176	            .iter()
177	            .filter(|c| {
178	                c.bloom_target <= max_level
179	                    && !mastered.contains(&c.name)
180	                    && c.prerequisites.iter().all(|p| mastered.contains(p))
181	            })
182	            .collect()
183	    }
184	}
