158	
159	    fn sym(n: u64) -> SymbolId {
160	        SymbolId::new(n).unwrap()
161	    }
162	
163	    fn make_triple(s: u64, p: u64, o: u64) -> Triple {
164	        Triple::new(sym(s), sym(p), sym(o))
165	    }
166	
167	    fn make_cluster(n_triples: usize, n_predicates: usize, freq: f32) -> CoActivationCluster {
168	        let mut triples = Vec::new();
169	        for i in 0..n_triples {
170	            triples.push(make_triple(
171	                100 + i as u64,
172	                (i % n_predicates) as u64 + 1,
173	                200 + i as u64,
174	            ));
175	        }
176	        CoActivationCluster {
177	            symbols: vec![sym(1), sym(2), sym(3)],
178	            frequency: freq,
179	            induced_triples: triples,
180	        }
181	    }
182	
