191	    fn quality_threshold_fails_too_few_triples() {
192	        let cluster = make_cluster(3, 3, 5.0);
193	        let config = DiscoveryConfig::default();
194	        assert!(!meets_quality_threshold(&cluster, &config));
195	    }
196	
197	    #[test]
198	    fn quality_threshold_fails_low_frequency() {
199	        let cluster = make_cluster(10, 3, 1.0);
200	        let config = DiscoveryConfig::default();
201	        assert!(!meets_quality_threshold(&cluster, &config));
202	    }
203	
204	    #[test]
205	    fn discover_from_clusters_filters_correctly() {
206	        let good = make_cluster(10, 3, 5.0);
207	        let bad = make_cluster(2, 1, 1.0);
208	        let config = DiscoveryConfig::default();
209	
210	        let candidates = discover_from_clusters(&[good, bad], &config);
211	        assert_eq!(candidates.len(), 1);
212	    }
213	
214	    #[test]
215	    fn build_candidate_has_correct_triple_count() {
216	        let cluster = make_cluster(7, 2, 4.0);
217	        let candidate = build_candidate_from_cluster(&cluster, "test-token".to_string());
218	        assert_eq!(candidate.core_triples.len(), 7);
219	        assert_eq!(candidate.provenance_token, "test-token");
220	    }
221	}
