164	            .map(|i| Triple::new(sym(i as u64 + 1), sym(10), sym(i as u64 + 100)))
165	            .collect()
166	    }
167	
168	    #[test]
169	    fn sufficient_content_produces_candidate() {
170	        let request = SynthesisRequest {
171	            gap: make_gap("robotics"),
172	            max_triples: 100,
173	            require_approval: true,
174	        };
175	        let resources = IngestedResources {
176	            triples: make_triples(20),
177	            sources: vec!["https://example.com".to_string()],
178	            bytes_ingested: 1024,
179	        };
180	
181	        let result = synthesize_from_resources(&request, resources, 5);
182	        assert!(matches!(result, SynthesisResult::Candidate(_)));
183	        if let SynthesisResult::Candidate(c) = result {
184	            assert_eq!(c.suggested_name, "robotics");
185	            assert_eq!(c.core_triples.len(), 20);
186	        }
187	    }
188	
189	    #[test]
190	    fn insufficient_content_returns_error() {
191	        let request = SynthesisRequest {
192	            gap: make_gap("exotic_domain"),
193	            ..Default::default()
194	        };
195	        let resources = IngestedResources {
196	            triples: make_triples(2),
197	            sources: Vec::new(),
198	            bytes_ingested: 100,
199	        };
200	
201	        let result = synthesize_from_resources(&request, resources, 5);
202	        assert!(matches!(
203	            result,
204	            SynthesisResult::InsufficientContent {
205	                triples_found: 2,
206	                ..
207	            }
208	        ));
209	    }
210	
211	    #[test]
212	    fn gap_coverage_detected() {
213	        let sims = vec![("math".to_string(), 0.45), ("physics".to_string(), 0.82)];
214	        let covering = check_gap_coverage(&sims, 0.75);
215	        assert_eq!(covering, Some("physics".to_string()));
216	    }
