219	    fn gap_coverage_below_threshold() {
220	        let sims = vec![("math".to_string(), 0.45), ("physics".to_string(), 0.60)];
221	        let covering = check_gap_coverage(&sims, 0.75);
222	        assert!(covering.is_none());
223	    }
