1	//! Skill manager: discover, warm, activate, and deactivate skillpacks.
2	//!
3	//! Scans a skills directory for subdirectories containing `skill.json` manifests.
4	//! Each skill follows the lifecycle: Cold → Warm → Hot.
5	//!
6	//! Extended in Phase 31:
7	//! - 31a: dependency-graph-aware activation (via `graph.rs`)
8	//! - 31b: per-skill neural prototype storage and query matching
9	//! - 31c: last-used tracking for idle-deactivation routing
10	
11	use std::collections::HashMap;
12	use std::path::PathBuf;
13	use std::sync::RwLock;
14	use std::sync::atomic::{AtomicUsize, Ordering};
15	use std::time::{Duration, Instant};
16	
17	use dashmap::DashMap;
18	use egg::{Pattern, Rewrite};
19	
20	use crate::error::{SkillError, SkillResult};
21	use crate::graph::Triple;
22	use crate::graph::index::KnowledgeGraph;
23	use crate::reason::AkhLang;
24	use crate::symbol::SymbolId;
25	use crate::vsa::HyperVec;
26	use crate::vsa::encode::encode_symbol;
27	use crate::vsa::ops::VsaOps;
28	
29	use super::{LoadedSkill, SkillActivation, SkillInfo, SkillManifest, SkillState};
30	
31	/// Manages the lifecycle of skillpacks.
32	pub struct SkillManager {
33	    skills_dir: PathBuf,
34	    skills: RwLock<HashMap<String, LoadedSkill>>,
35	    loaded_bytes: AtomicUsize,
36	    max_bytes: usize,
37	    /// Stored rule text per skill: skill_id -> Vec<(name, lhs, rhs)>.
38	    #[allow(clippy::type_complexity)]
39	    rule_sources: RwLock<HashMap<String, Vec<(String, String, String)>>>,
40	    /// Triples loaded from each active skill (skill_id → triples).
41	    /// Used by Phase 31b prototype computation.
42	    skill_triples: RwLock<HashMap<String, Vec<Triple>>>,
43	    /// Neural prototype per skill (skill_id → serialised HyperVec bytes).
44	    /// Populated at activation time via `compute_and_store_prototype`.
45	    prototypes: DashMap<String, Vec<u8>>,
46	    /// Last-access timestamp per Hot skill (Phase 31c idle-deactivation).
47	    last_used: DashMap<String, Instant>,
48	}
49	
50	impl std::fmt::Debug for SkillManager {
51	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
52	        f.debug_struct("SkillManager")
53	            .field("skills_dir", &self.skills_dir)
54	            .field("loaded_bytes", &self.loaded_bytes.load(Ordering::Relaxed))
55	            .field("max_bytes", &self.max_bytes)
56	            .finish()
57	    }
58	}
59	
60	impl SkillManager {
61	    /// Create a new skill manager.
62	    ///
63	    /// `max_memory_mb` is the total memory budget for loaded skillpacks.
64	    pub fn new(skills_dir: PathBuf, max_memory_mb: usize) -> Self {
65	        Self {
66	            skills_dir,
67	            skills: RwLock::new(HashMap::new()),
68	            loaded_bytes: AtomicUsize::new(0),
69	            max_bytes: max_memory_mb * 1024 * 1024,
70	            rule_sources: RwLock::new(HashMap::new()),
71	            skill_triples: RwLock::new(HashMap::new()),
72	            prototypes: DashMap::new(),
73	            last_used: DashMap::new(),
74	        }
75	    }
76	
77	    /// Get the skills directory path.
78	    pub fn skills_dir(&self) -> &std::path::Path {
79	        &self.skills_dir
80	    }
81	
82	    /// Scan the skills directory for subdirectories containing `skill.json`.
83	    ///
84	    /// Registers each found skill as Cold. Returns the number of skills discovered.
85	    pub fn discover(&self) -> SkillResult<usize> {
86	        if !self.skills_dir.exists() {
87	            return Err(SkillError::NoSkillsDir {
88	                path: self.skills_dir.display().to_string(),
89	            });
90	        }
91	
92	        let entries = std::fs::read_dir(&self.skills_dir).map_err(|e| SkillError::Io {
93	            skill_id: "<discovery>".into(),
94	            source: e,
95	        })?;
96	
97	        let mut count = 0;
98	        let mut skills = self.skills.write().expect("skills lock poisoned");
99	
100	        for entry in entries {
101	            let entry = entry.map_err(|e| SkillError::Io {
102	                skill_id: "<discovery>".into(),
103	                source: e,
104	            })?;
105	            let path = entry.path();
106	            if !path.is_dir() {
107	                continue;
108	            }
109	
110	            let manifest_path = path.join("skill.json");
111	            if !manifest_path.exists() {
112	                continue;
113	            }
114	
115	            // Use the directory name as the skill ID for discovery.
116	            let skill_id = path
117	                .file_name()
118	                .and_then(|n| n.to_str())
119	                .unwrap_or("unknown")
120	                .to_string();
121	
122	            if !skills.contains_key(&skill_id) {
123	                skills.insert(
124	                    skill_id.clone(),
125	                    LoadedSkill {
126	                        manifest: SkillManifest {
127	                            id: skill_id,
128	                            name: String::new(),
129	                            version: String::new(),
130	                            description: String::new(),
131	                            domains: Vec::new(),
132	                            weight_size_bytes: 0,
133	                            triples_file: None,
134	                            rules_file: None,
135	                            cli_tools: Vec::new(),
136	                            wasm_tools: Vec::new(),
137	                            tool_config: std::collections::HashMap::new(),
138	                            depends: Vec::new(),
139	                            conflicts: Vec::new(),
140	                            provides: Vec::new(),
141	                            requires: Vec::new(),
142	                            remote_url: None,
143	                            curriculum_file: None,
144	                        },
145	                        state: SkillState::Cold,
146	                        triple_count: 0,
147	                        rule_count: 0,
148	                        memory_bytes: 0,
149	                        last_used_at: None,
150	                    },
151	                );
152	                count += 1;
153	            }
154	        }
155	
156	        Ok(count)
157	    }
158	
159	    /// Parse the manifest for a Cold skill, transitioning it to Warm.
160	    pub fn warm(&self, skill_id: &str) -> SkillResult<SkillManifest> {
161	        let mut skills = self.skills.write().expect("skills lock poisoned");
162	        let skill = skills
163	            .get_mut(skill_id)
164	            .ok_or_else(|| SkillError::NotFound {
165	                name: skill_id.into(),
166	            })?;
167	
168	        if skill.state != SkillState::Cold {
169	            return Err(SkillError::InvalidTransition {
170	                skill_id: skill_id.into(),
171	                from: skill.state.to_string(),
172	                to: "Warm".into(),
173	            });
174	        }
175	
176	        let manifest_path = self.skills_dir.join(skill_id).join("skill.json");
177	        let content = std::fs::read_to_string(&manifest_path).map_err(|e| SkillError::Io {
178	            skill_id: skill_id.into(),
179	            source: e,
180	        })?;
181	
182	        let manifest: SkillManifest =
183	            serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
184	                path: manifest_path.display().to_string(),
185	                message: e.to_string(),
186	            })?;
187	
188	        skill.manifest = manifest.clone();
189	        skill.state = SkillState::Warm;
190	
191	        Ok(manifest)
192	    }
193	
194	    /// Activate a Warm skill: load triples into the knowledge graph
195	    /// and parse rules. Transitions the skill to Hot.
196	    ///
197	    /// Phase 31a: checks for conflicts with currently active skills before
198	    /// loading. Phase 31c: records the activation timestamp.
199	    pub fn activate(
200	        &self,
201	        skill_id: &str,
202	        knowledge_graph: &KnowledgeGraph,
203	    ) -> SkillResult<SkillActivation> {
204	        // Phase 31a: conflict check against currently active skills.
205	        let active_ids = self.active_skill_ids();
206	        {
207	            let skills = self.skills.read().expect("skills lock poisoned");
208	            if let Some(skill) = skills.get(skill_id) {
209	                if let Some(conflict) = super::graph::SkillDependencyGraph::check_conflicts(
210	                    &skill.manifest,
211	                    &active_ids,
212	                ) {
213	                    return Err(SkillError::SkillConflict {
214	                        skill_id: skill_id.into(),
215	                        conflict,
216	                    });
217	                }
218	            }
219	        }
220	
221	        let mut skills = self.skills.write().expect("skills lock poisoned");
222	        let skill = skills
223	            .get_mut(skill_id)
224	            .ok_or_else(|| SkillError::NotFound {
225	                name: skill_id.into(),
226	            })?;
227	
228	        if skill.state != SkillState::Warm {
229	            return Err(SkillError::InvalidTransition {
230	                skill_id: skill_id.into(),
231	                from: skill.state.to_string(),
232	                to: "Hot".into(),
233	            });
234	        }
235	
236	        let skill_dir = self.skills_dir.join(skill_id);
237	        let mut triples_loaded = 0usize;
238	        let mut rules_loaded = 0usize;
239	        let mut memory_estimate = 0usize;
240	        let mut loaded_triples: Vec<Triple> = Vec::new();
241	
242	        // Load triples if available.
243	        let triples_file = skill
244	            .manifest
245	            .triples_file
246	            .clone()
247	            .unwrap_or_else(|| "triples.json".into());
248	        let triples_path = skill_dir.join(&triples_file);
249	        if triples_path.exists() {
250	            let content = std::fs::read_to_string(&triples_path).map_err(|e| SkillError::Io {
251	                skill_id: skill_id.into(),
252	                source: e,
253	            })?;
254	
255	            let raw_triples: Vec<serde_json::Value> =
256	                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
257	                    path: triples_path.display().to_string(),
258	                    message: format!("triples parse error: {e}"),
259	                })?;
260	
261	            for val in &raw_triples {
262	                let s = val["s"].as_u64().unwrap_or(0);
263	                let p = val["p"].as_u64().unwrap_or(0);
264	                let o = val["o"].as_u64().unwrap_or(0);
265	
266	                if let (Some(s), Some(p), Some(o)) =
267	                    (SymbolId::new(s), SymbolId::new(p), SymbolId::new(o))
268	                {
269	                    let triple = Triple::new(s, p, o);
270	                    // Ignore duplicate triple errors.
271	                    let _ = knowledge_graph.insert_triple(&triple);
272	                    loaded_triples.push(triple);
273	                    triples_loaded += 1;
274	                }
275	            }
276	
277	            memory_estimate += content.len();
278	        }
279	
280	        // Load rules if available.
281	        let rules_file = skill
282	            .manifest
283	            .rules_file
284	            .clone()
285	            .unwrap_or_else(|| "rules.txt".into());
286	        let rules_path = skill_dir.join(&rules_file);
287	        let mut rule_tuples: Vec<(String, String, String)> = Vec::new();
288	        if rules_path.exists() {
289	            let content = std::fs::read_to_string(&rules_path).map_err(|e| SkillError::Io {
290	                skill_id: skill_id.into(),
291	                source: e,
292	            })?;
293	
294	            for (i, line) in content.lines().enumerate() {
295	                let line = line.trim();
296	                if line.is_empty() || line.starts_with('#') {
297	                    continue;
298	                }
299	                if let Some((lhs, rhs)) = line.split_once("=>") {
300	                    let name = format!("{}-rule-{}", skill_id, i);
301	                    rule_tuples.push((name, lhs.trim().to_string(), rhs.trim().to_string()));
302	                    rules_loaded += 1;
303	                } else {
304	                    return Err(SkillError::InvalidRule {
305	                        skill_id: skill_id.into(),
306	                        message: format!("line {}: missing '=>' separator", i + 1),
307	                    });
308	                }
309	            }
310	
311	            memory_estimate += content.len();
312	        }
313	
314	        // Check memory budget.
315	        let current = self.loaded_bytes.load(Ordering::Relaxed);
316	        if current + memory_estimate > self.max_bytes {
317	            return Err(SkillError::MemoryBudgetExceeded {
318	                required_mb: memory_estimate / (1024 * 1024) + 1,
319	                available_mb: (self.max_bytes.saturating_sub(current)) / (1024 * 1024),
320	            });
321	        }
322	
323	        // Commit.
324	        self.loaded_bytes
325	            .fetch_add(memory_estimate, Ordering::Relaxed);
326	        skill.state = SkillState::Hot;
327	        skill.triple_count = triples_loaded;
328	        skill.rule_count = rules_loaded;
329	        skill.memory_bytes = memory_estimate;
330	        // Phase 31c: record activation time.
331	        skill.last_used_at = Some(Instant::now());
332	
333	        if !rule_tuples.is_empty() {
334	            self.rule_sources
335	                .write()
336	                .expect("rule_sources lock poisoned")
337	                .insert(skill_id.to_string(), rule_tuples);
338	        }
339	
340	        // Phase 31b: store triples for prototype computation.
341	        if !loaded_triples.is_empty() {
342	            self.skill_triples
343	                .write()
344	                .expect("skill_triples lock poisoned")
345	                .insert(skill_id.to_string(), loaded_triples);
346	        }
347	
348	        // Phase 31c: record last-used timestamp.
349	        self.last_used.insert(skill_id.to_string(), Instant::now());
350	
351	        Ok(SkillActivation {
352	            skill_id: skill_id.into(),
353	            triples_loaded,
354	            rules_loaded,
355	            memory_bytes: memory_estimate,
356	        })
357	    }
358	
359	    /// Deactivate a Hot skill: mark inactive, free budget.
360	    /// Triples already in the KG persist until engine restart.
361	    pub fn deactivate(&self, skill_id: &str) -> SkillResult<()> {
362	        let mut skills = self.skills.write().expect("skills lock poisoned");
363	        let skill = skills
364	            .get_mut(skill_id)
365	            .ok_or_else(|| SkillError::NotFound {
366	                name: skill_id.into(),
367	            })?;
368	
369	        if skill.state != SkillState::Hot {
370	            return Err(SkillError::InvalidTransition {
371	                skill_id: skill_id.into(),
372	                from: skill.state.to_string(),
373	                to: "Warm (deactivate)".into(),
374	            });
375	        }
376	
377	        self.loaded_bytes
378	            .fetch_sub(skill.memory_bytes, Ordering::Relaxed);
379	        skill.state = SkillState::Warm;
380	        skill.memory_bytes = 0;
381	        skill.last_used_at = None;
382	
383	        self.rule_sources
384	            .write()
385	            .expect("rule_sources lock poisoned")
386	            .remove(skill_id);
387	
388	        // Phase 31b/c: clear per-skill data.
389	        self.skill_triples
390	            .write()
391	            .expect("skill_triples lock poisoned")
392	            .remove(skill_id);
393	        self.prototypes.remove(skill_id);
394	        self.last_used.remove(skill_id);
395	
396	        Ok(())
397	    }
398	
399	    /// Get the current state of a skill, or `None` if not discovered.
400	    pub fn skill_state(&self, skill_id: &str) -> Option<SkillState> {
401	        let skills = self.skills.read().expect("skills lock poisoned");
402	        skills.get(skill_id).map(|s| s.state)
403	    }
404	
405	    /// Build an activation summary for an already-Hot skill (idempotent reload).
406	    pub fn hot_activation(&self, skill_id: &str) -> Option<SkillActivation> {
407	        let skills = self.skills.read().expect("skills lock poisoned");
408	        let skill = skills.get(skill_id)?;
409	        if skill.state != SkillState::Hot {
410	            return None;
411	        }
412	        Some(SkillActivation {
413	            skill_id: skill_id.to_string(),
414	            triples_loaded: skill.triple_count,
415	            rules_loaded: skill.rule_count,
416	            memory_bytes: skill.memory_bytes,
417	        })
418	    }
419	
420	    /// Add extra triples to a Hot skill's count (e.g. label triples loaded externally).
421	    pub fn add_triple_count(&self, skill_id: &str, extra: usize) {
422	        let mut skills = self.skills.write().expect("skills lock poisoned");
423	        if let Some(skill) = skills.get_mut(skill_id) {
424	            skill.triple_count += extra;
425	        }
426	    }
427	
428	    /// List all known skills with their current state.
429	    pub fn list(&self) -> Vec<SkillInfo> {
430	        let skills = self.skills.read().expect("skills lock poisoned");
431	        skills
432	            .values()
433	            .map(|s| SkillInfo {
434	                id: s.manifest.id.clone(),
435	                name: s.manifest.name.clone(),
436	                version: s.manifest.version.clone(),
437	                description: s.manifest.description.clone(),
438	                state: s.state,
439	                domains: s.manifest.domains.clone(),
440	                triple_count: s.triple_count,
441	                rule_count: s.rule_count,
442	                provides: s.manifest.provides.clone(),
443	                requires: s.manifest.requires.clone(),
444	            })
445	            .collect()
446	    }
447	
448	    /// Build rewrite rules from all active (Hot) skills.
449	    pub fn active_rules(&self) -> Vec<Rewrite<AkhLang, ()>> {
450	        let rule_sources = self
451	            .rule_sources
452	            .read()
453	            .expect("rule_sources lock poisoned");
454	        let mut rules = Vec::new();
455	
456	        for (skill_id, tuples) in rule_sources.iter() {
457	            for (name, lhs, rhs) in tuples {
458	                // egg::rewrite! is a macro; we must use the lower-level API.
459	                let lhs_result: Result<Pattern<AkhLang>, _> = lhs.parse();
460	                let rhs_result: Result<Pattern<AkhLang>, _> = rhs.parse();
461	                if let (Ok(lhs_pat), Ok(rhs_pat)) = (lhs_result, rhs_result) {
462	                    match Rewrite::new(name.clone(), lhs_pat, rhs_pat) {
463	                        Ok(rule) => rules.push(rule),
464	                        Err(e) => {
465	                            tracing::warn!(
466	                                skill_id,
467	                                rule = name.as_str(),
468	                                error = %e,
469	                                "failed to compile skill rule, skipping"
470	                            );
471	                        }
472	                    }
473	                } else {
474	                    tracing::warn!(
475	                        skill_id,
476	                        rule = name.as_str(),
477	                        "failed to parse skill rule patterns, skipping"
478	                    );
479	                }
480	            }
481	        }
482	
483	        rules
484	    }
485	
486	    /// Get info for a specific skill.
487	    pub fn get_info(&self, skill_id: &str) -> SkillResult<SkillInfo> {
488	        let skills = self.skills.read().expect("skills lock poisoned");
489	        let skill = skills.get(skill_id).ok_or_else(|| SkillError::NotFound {
490	            name: skill_id.into(),
491	        })?;
492	        Ok(SkillInfo {
493	            id: skill.manifest.id.clone(),
494	            name: skill.manifest.name.clone(),
495	            version: skill.manifest.version.clone(),
496	            description: skill.manifest.description.clone(),
497	            state: skill.state,
498	            domains: skill.manifest.domains.clone(),
499	            triple_count: skill.triple_count,
500	            rule_count: skill.rule_count,
501	            provides: skill.manifest.provides.clone(),
502	            requires: skill.manifest.requires.clone(),
503	        })
504	    }
505	
506	    // ── Phase 31b: Neural skill embeddings ───────────────────────────────────
507	
508	    /// Return the triples loaded from a specific skill (Phase 31b).
509	    ///
510	    /// Only populated for currently-Hot skills loaded via the numeric triple
511	    /// path. Label-based triples loaded through `engine.load_skill_with_labels`
512	    /// are not tracked here.
513	    pub fn triples_of_skill(&self, skill_id: &str) -> Vec<Triple> {
514	        self.skill_triples
515	            .read()
516	            .expect("skill_triples lock poisoned")
517	            .get(skill_id)
518	            .cloned()
519	            .unwrap_or_default()
520	    }
521	
522	    /// Compute and store a neural prototype HyperVec for a skill (Phase 31b).
523	    ///
524	    /// The prototype is the bundle of all symbol vectors for the skill's
525	    /// triples (subject, predicate, object). Stored as serialised bytes under
526	    /// the skill's ID; retrieve with `prototype_bytes`.
527	    ///
528	    /// Call this after `activate` for skills where semantic matching is needed.
529	    /// Returns `None` if the skill has no triples to bundle.
530	    pub fn compute_and_store_prototype(&self, skill_id: &str, ops: &VsaOps) -> Option<()> {
531	        let triples = self.triples_of_skill(skill_id);
532	        if triples.is_empty() {
533	            return None;
534	        }
535	
536	        // Encode each triple's symbols.
537	        let vecs: Vec<HyperVec> = triples
538	            .iter()
539	            .flat_map(|t| {
540	                [
541	                    encode_symbol(ops, t.subject),
542	                    encode_symbol(ops, t.predicate),
543	                    encode_symbol(ops, t.object),
544	                ]
545	            })
546	            .collect();
547	
548	        let refs: Vec<&HyperVec> = vecs.iter().collect();
549	        let prototype = ops.bundle(&refs).ok()?;
550	
551	        // Serialise to bytes for compact storage.
552	        let bytes = bincode::serialize(&prototype).ok()?;
553	        self.prototypes.insert(skill_id.to_string(), bytes);
554	        Some(())
555	    }
556	
557	    /// Retrieve the stored prototype bytes for a skill (Phase 31b).
558	    ///
559	    /// Returns `None` if no prototype has been computed for this skill.
560	    pub fn prototype_bytes(&self, skill_id: &str) -> Option<Vec<u8>> {
561	        self.prototypes.get(skill_id).map(|b| b.value().clone())
562	    }
563	
564	    /// Deserialise and return the prototype HyperVec for a skill (Phase 31b).
565	    ///
566	    /// Returns `None` if no prototype is stored for this skill.
567	    pub fn prototype(&self, skill_id: &str) -> Option<HyperVec> {
568	        let bytes = self.prototype_bytes(skill_id)?;
569	        bincode::deserialize(&bytes).ok()
570	    }
571	
572	    /// Find the `k` most similar skills to a query HyperVec (Phase 31b/c).
573	    ///
574	    /// Returns a list of `(skill_id, similarity)` pairs sorted by descending
575	    /// similarity. Only considers skills that have a stored prototype.
576	    pub fn match_skills_to_query(
577	        &self,
578	        query: &HyperVec,
579	        ops: &VsaOps,
580	        k: usize,
581	        threshold: f32,
582	    ) -> Vec<(String, f32)> {
583	        let mut matches: Vec<(String, f32)> = self
584	            .prototypes
585	            .iter()
586	            .filter_map(|entry| {
587	                let skill_id = entry.key().clone();
588	                let proto: HyperVec = bincode::deserialize(entry.value()).ok()?;
589	                let sim = ops.similarity(query, &proto).ok()?;
590	                if sim >= threshold {
591	                    Some((skill_id, sim))
592	                } else {
593	                    None
594	                }
595	            })
596	            .collect();
597	
598	        matches.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
599	        matches.truncate(k);
600	        matches
601	    }
602	
603	    // ── Phase 31c: Skill-aware routing and idle deactivation ─────────────────
604	
605	    /// Record that a skill was just used (Phase 31c).
606	    ///
607	    /// Updates both the `last_used` map and the `LoadedSkill.last_used_at` field.
608	    pub fn touch_skill(&self, skill_id: &str) {
609	        self.last_used.insert(skill_id.to_string(), Instant::now());
610	        let mut skills = self.skills.write().expect("skills lock poisoned");
611	        if let Some(skill) = skills.get_mut(skill_id) {
612	            skill.last_used_at = Some(Instant::now());
613	        }
614	    }
615	
616	    /// Return the IDs of skills that have been idle longer than `cooldown` (Phase 31c).
617	    ///
618	    /// These are candidates for auto-deactivation to free memory.
619	    pub fn collect_idle_skills(&self, cooldown: Duration) -> Vec<String> {
620	        let now = Instant::now();
621	        self.last_used
622	            .iter()
623	            .filter(|entry| now.duration_since(*entry.value()) > cooldown)
624	            .map(|entry| entry.key().clone())
625	            .collect()
626	    }
627	
628	    /// Return the IDs of all currently-Hot skills.
629	    pub fn active_skill_ids(&self) -> Vec<String> {
630	        let skills = self.skills.read().expect("skills lock poisoned");
631	        skills
632	            .iter()
633	            .filter(|(_, s)| s.state == SkillState::Hot)
634	            .map(|(id, _)| id.clone())
635	            .collect()
636	    }
637	
638	    /// Return all known skill manifests (for graph construction).
639	    pub fn all_manifests(&self) -> HashMap<String, SkillManifest> {
640	        let skills = self.skills.read().expect("skills lock poisoned");
641	        skills
642	            .iter()
643	            .map(|(id, s)| (id.clone(), s.manifest.clone()))
644	            .collect()
645	    }
646	
647	    /// Compute the activation plan for a target skill using the dependency graph.
648	    ///
649	    /// Returns an ordered list of skill IDs to activate (dependencies first),
650	    /// excluding already-active skills. Returns an error for circular dependencies
651	    /// or conflicts.
652	    pub fn activation_plan(&self, target_skill_id: &str) -> SkillResult<Vec<String>> {
653	        let all_manifests = self.all_manifests();
654	        let active_ids = self.active_skill_ids();
655	        super::graph::compute_activation_plan(target_skill_id, &all_manifests, &active_ids)
656	    }
657	}
