1	//! Skill dependency graph: topological activation ordering and conflict detection.
2	//!
3	//! Phase 31a — builds a petgraph DAG from skill manifests, performs topological
4	//! sort for safe multi-skill activation, detects circular dependencies and
5	//! conflicts, and resolves loose capability requirements to concrete providers.
6	
7	use std::collections::HashMap;
8	
9	use petgraph::algo::toposort;
10	use petgraph::graph::{DiGraph, NodeIndex};
11	use petgraph::visit::EdgeRef;
12	
13	use crate::error::{SkillError, SkillResult};
14	
15	use super::SkillManifest;
16	
17	/// Direction of a dependency edge in the graph.
18	///
19	/// An edge `A → B` means "A depends on B" (B must be activated first).
20	type DepEdge = ();
21	
22	/// A directed acyclic graph of skill dependencies.
23	///
24	/// Nodes are skill IDs; edges point from dependent to dependency
25	/// (`A → B` = "A needs B active before it can activate").
26	pub struct SkillDependencyGraph {
27	    graph: DiGraph<String, DepEdge>,
28	    node_index: HashMap<String, NodeIndex>,
29	}
30	
31	impl Default for SkillDependencyGraph {
32	    fn default() -> Self {
33	        Self::new()
34	    }
35	}
36	
37	impl SkillDependencyGraph {
38	    pub fn new() -> Self {
39	        Self {
40	            graph: DiGraph::new(),
41	            node_index: HashMap::new(),
42	        }
43	    }
44	
45	    /// Ensure a skill node exists; return its `NodeIndex`.
46	    pub fn add_skill(&mut self, skill_id: &str) -> NodeIndex {
47	        if let Some(&idx) = self.node_index.get(skill_id) {
48	            return idx;
49	        }
50	        let idx = self.graph.add_node(skill_id.to_string());
51	        self.node_index.insert(skill_id.to_string(), idx);
52	        idx
53	    }
54	
55	    /// Add a dependency edge: `dependent` → `dependency`.
56	    ///
57	    /// Both nodes are created if not already present.
58	    pub fn add_dependency(&mut self, dependent: &str, dependency: &str) {
59	        let dep_node = self.add_skill(dependent);
60	        let req_node = self.add_skill(dependency);
61	        // Only add if the edge doesn't already exist.
62	        if !self.graph.contains_edge(dep_node, req_node) {
63	            self.graph.add_edge(dep_node, req_node, ());
64	        }
65	    }
66	
67	    /// Build a dependency graph from a collection of manifests.
68	    ///
69	    /// Adds all skills and their declared `depends` edges.
70	    pub fn from_manifests<'a>(manifests: impl IntoIterator<Item = &'a SkillManifest>) -> Self {
71	        let mut g = Self::new();
72	        for m in manifests {
73	            g.add_skill(&m.id);
74	            for dep in &m.depends {
75	                g.add_dependency(&m.id, dep);
76	            }
77	        }
78	        g
79	    }
80	
81	    /// Return the order in which skills should be activated so every skill's
82	    /// dependencies are activated before it.
83	    ///
84	    /// The returned list is ordered from "must be activated first" to last.
85	    /// Returns `SkillError::CircularDependency` if the graph has a cycle.
86	    pub fn activation_order(&self) -> SkillResult<Vec<String>> {
87	        // toposort returns nodes in topological order (dependencies before dependents
88	        // when edges go dependent → dependency, so reverse).
89	        match toposort(&self.graph, None) {
90	            Ok(order) => {
91	                // Reverse so dependencies come first.
92	                let skills: Vec<String> = order
93	                    .into_iter()
94	                    .rev()
95	                    .map(|idx| self.graph[idx].clone())
96	                    .collect();
97	                Ok(skills)
98	            }
99	            Err(cycle) => {
100	                let node_label = self.graph[cycle.node_id()].clone();
101	                Err(SkillError::CircularDependency {
102	                    cycle: vec![node_label],
103	                })
104	            }
105	        }
106	    }
107	
108	    /// Return the skills that directly depend on `skill_id` (its reverse dependencies).
109	    ///
110	    /// Used during deactivation to warn if dependents are still active.
111	    pub fn dependents_of(&self, skill_id: &str) -> Vec<String> {
112	        let Some(&idx) = self.node_index.get(skill_id) else {
113	            return Vec::new();
114	        };
115	        // Edges go dependent → dependency; we want nodes that point TO skill_id.
116	        self.graph
117	            .edges_directed(idx, petgraph::Direction::Incoming)
118	            .map(|e| self.graph[e.source()].clone())
119	            .collect()
120	    }
121	
122	    /// Return the skill IDs that `skill_id` directly depends on.
123	    pub fn dependencies_of(&self, skill_id: &str) -> Vec<String> {
124	        let Some(&idx) = self.node_index.get(skill_id) else {
125	            return Vec::new();
126	        };
127	        self.graph
128	            .edges_directed(idx, petgraph::Direction::Outgoing)
129	            .map(|e| self.graph[e.target()].clone())
130	            .collect()
131	    }
132	
133	    /// Check if activating `skill_id` would conflict with any currently-active skills.
134	    ///
135	    /// Returns the first conflicting skill ID found, or `None` if there are no conflicts.
136	    pub fn check_conflicts(
137	        manifest: &SkillManifest,
138	        active_skill_ids: &[String],
139	    ) -> Option<String> {
140	        for active in active_skill_ids {
141	            if manifest.conflicts.contains(active) {
142	                return Some(active.clone());
143	            }
144	        }
145	        None
146	    }
147	
148	    /// Resolve capability requirements: for each entry in `requires`, find the
149	    /// skill IDs that `provide` it.
150	    ///
151	    /// Returns `Ok(providers)` — a deduplicated list of skill IDs that together
152	    /// satisfy all capabilities in `requires`.
153	    ///
154	    /// Returns `Err(UnresolvedCapability)` if any capability has no provider.
155	    pub fn resolve_capabilities<'a>(
156	        requires: &[String],
157	        all_manifests: impl IntoIterator<Item = &'a SkillManifest>,
158	    ) -> SkillResult<Vec<String>> {
159	        let manifests: Vec<&SkillManifest> = all_manifests.into_iter().collect();
160	        let mut providers: Vec<String> = Vec::new();
161	
162	        for cap in requires {
163	            let found = manifests.iter().any(|m| m.provides.contains(cap));
164	            if !found {
165	                return Err(SkillError::UnresolvedCapability {
166	                    capability: cap.clone(),
167	                });
168	            }
169	            // Collect providers for this capability.
170	            for m in &manifests {
171	                if m.provides.contains(cap) && !providers.contains(&m.id) {
172	                    providers.push(m.id.clone());
173	                }
174	            }
175	        }
176	
177	        Ok(providers)
178	    }
179	}
180	
181	/// Compute the full activation plan for a target skill given a set of all known
182	/// manifests and a set of currently active skill IDs.
183	///
184	/// Returns an ordered list of skill IDs to activate (dependencies first).
185	/// Already-active skills are excluded from the returned list.
186	pub fn compute_activation_plan(
187	    target_skill_id: &str,
188	    all_manifests: &HashMap<String, SkillManifest>,
189	    active_skill_ids: &[String],
190	) -> SkillResult<Vec<String>> {
191	    // Collect the transitive closure of dependencies via BFS/DFS.
192	    let mut visited: std::collections::HashSet<String> = std::collections::HashSet::new();
193	    let mut stack: Vec<String> = vec![target_skill_id.to_string()];
194	    let mut relevant: Vec<SkillManifest> = Vec::new();
195	
196	    while let Some(id) = stack.pop() {
197	        if visited.contains(&id) {
198	            continue;
199	        }
200	        visited.insert(id.clone());
201	
202	        if let Some(m) = all_manifests.get(&id) {
203	            // Check conflicts with already-active skills.
204	            if let Some(conflict) = SkillDependencyGraph::check_conflicts(m, active_skill_ids) {
205	                return Err(SkillError::SkillConflict {
206	                    skill_id: id.clone(),
207	                    conflict,
208	                });
209	            }
210	            for dep in &m.depends {
211	                if !visited.contains(dep) {
212	                    stack.push(dep.clone());
213	                }
214	            }
215	            relevant.push(m.clone());
216	        }
217	        // Unknown dependency IDs are ignored here; the caller may choose to error.
218	    }
219	
220	    let g = SkillDependencyGraph::from_manifests(relevant.iter());
221	    let order = g.activation_order()?;
