148	    /// Resolve capability requirements: for each entry in `requires`, find the
149	    /// skill IDs that `provide` it.
150	    ///
151	    /// Returns `Ok(providers)` — a deduplicated list of skill IDs that together
152	    /// satisfy all capabilities in `requires`.
153	    ///
154	    /// Returns `Err(UnresolvedCapability)` if any capability has no provider.
155	    pub fn resolve_capabilities<'a>(
156	        requires: &[String],
157	        all_manifests: impl IntoIterator<Item = &'a SkillManifest>,
158	    ) -> SkillResult<Vec<String>> {
159	        let manifests: Vec<&SkillManifest> = all_manifests.into_iter().collect();
160	        let mut providers: Vec<String> = Vec::new();
161	
162	        for cap in requires {
163	            let found = manifests.iter().any(|m| m.provides.contains(cap));
164	            if !found {
165	                return Err(SkillError::UnresolvedCapability {
166	                    capability: cap.clone(),
167	                });
168	            }
169	            // Collect providers for this capability.
170	            for m in &manifests {
171	                if m.provides.contains(cap) && !providers.contains(&m.id) {
172	                    providers.push(m.id.clone());
173	                }
174	            }
175	        }
176	
177	        Ok(providers)
178	    }
179	}
