101	/// Build a `SkillCandidate` from a cluster, using heuristic name and domain
102	/// inference.
103	///
104	/// In production, the `suggested_name` and `suggested_description` fields would
105	/// be populated by an LLM call (Phase 30c SkillAuthor). Here, we fill in
106	/// placeholders so the pipeline can function without an LLM dependency.
107	pub fn build_candidate_from_cluster(
108	    cluster: &CoActivationCluster,
109	    provenance_token: String,
110	) -> SkillCandidate {
111	    // Heuristic: use the first predicate string as a domain hint.
112	    let domain_hint = format!(
113	        "domain-{}",
114	        cluster.symbols.first().map(|s| s.get()).unwrap_or(0)
115	    );
116	
117	    SkillCandidate {
118	        suggested_name: format!(
119	            "auto-skill-{}",
120	            provenance_token.chars().take(8).collect::<String>()
121	        ),
122	        suggested_description: format!(
123	            "Auto-discovered skill with {} triples and {} symbols.",
124	            cluster.induced_triples.len(),
125	            cluster.symbols.len()
126	        ),
127	        domain_tags: vec![domain_hint],
128	        core_triples: cluster.induced_triples.clone(),
129	        related_rules: Vec::new(),
130	        confidence: (cluster.frequency / 10.0).min(1.0),
131	        provenance_token,
132	    }
