103	            triples_found: resources.triples.len(),
104	            min_required: min_triples,
105	        };
106	    }
107	
108	    let core_triples = resources
109	        .triples
110	        .into_iter()
111	        .take(request.max_triples)
112	        .collect();
113	
114	    let candidate = SkillCandidate {
115	        suggested_name: request.gap.suggested_name.clone(),
116	        suggested_description: request.gap.description.clone(),
117	        domain_tags: request.gap.domain_tags.clone(),
118	        core_triples,
119	        related_rules: Vec::new(),
120	        confidence: 0.6, // Moderate confidence for synthesized skills.
121	        provenance_token: request.gap.provenance_token.clone(),
122	    };
