168	    /// Return all concepts at or below the given Bloom level that have no
169	    /// unsatisfied prerequisites (given a set of already-mastered concepts).
170	    pub fn next_concepts<'a>(
171	        &'a self,
172	        mastered: &std::collections::HashSet<String>,
173	        max_level: BloomLevel,
174	    ) -> Vec<&'a CurriculumConcept> {
175	        self.concepts
176	            .iter()
177	            .filter(|c| {
178	                c.bloom_target <= max_level
179	                    && !mastered.contains(&c.name)
180	                    && c.prerequisites.iter().all(|p| mastered.contains(p))
181	            })
182	            .collect()
183	    }
184	}
