2	//!
3	//! Phase 31a — builds a petgraph DAG from skill manifests, performs topological
4	//! sort for safe multi-skill activation, detects circular dependencies and
5	//! conflicts, and resolves loose capability requirements to concrete providers.
6	
7	use std::collections::HashMap;
8	
