81	    /// Return the order in which skills should be activated so every skill's
82	    /// dependencies are activated before it.
83	    ///
84	    /// The returned list is ordered from "must be activated first" to last.
85	    /// Returns `SkillError::CircularDependency` if the graph has a cycle.
86	    pub fn activation_order(&self) -> SkillResult<Vec<String>> {
87	        // toposort returns nodes in topological order (dependencies before dependents
88	        // when edges go dependent → dependency, so reverse).
89	        match toposort(&self.graph, None) {
90	            Ok(order) => {
91	                // Reverse so dependencies come first.
92	                let skills: Vec<String> = order
93	                    .into_iter()
94	                    .rev()
95	                    .map(|idx| self.graph[idx].clone())
96	                    .collect();
97	                Ok(skills)
98	            }
99	            Err(cycle) => {
100	                let node_label = self.graph[cycle.node_id()].clone();
101	                Err(SkillError::CircularDependency {
102	                    cycle: vec![node_label],
103	                })
104	            }
105	        }
106	    }
