109	    ///
110	    /// Used during deactivation to warn if dependents are still active.
111	    pub fn dependents_of(&self, skill_id: &str) -> Vec<String> {
112	        let Some(&idx) = self.node_index.get(skill_id) else {
113	            return Vec::new();
114	        };
115	        // Edges go dependent → dependency; we want nodes that point TO skill_id.
116	        self.graph
117	            .edges_directed(idx, petgraph::Direction::Incoming)
118	            .map(|e| self.graph[e.source()].clone())
119	            .collect()
