181	/// Compute the full activation plan for a target skill given a set of all known
182	/// manifests and a set of currently active skill IDs.
183	///
184	/// Returns an ordered list of skill IDs to activate (dependencies first).
185	/// Already-active skills are excluded from the returned list.
186	pub fn compute_activation_plan(
