188	    all_manifests: &HashMap<String, SkillManifest>,
189	    active_skill_ids: &[String],
190	) -> SkillResult<Vec<String>> {
191	    // Collect the transitive closure of dependencies via BFS/DFS.
192	    let mut visited: std::collections::HashSet<String> = std::collections::HashSet::new();
193	    let mut stack: Vec<String> = vec![target_skill_id.to_string()];
194	    let mut relevant: Vec<SkillManifest> = Vec::new();
195	
196	    while let Some(id) = stack.pop() {
197	        if visited.contains(&id) {
198	            continue;
199	        }
200	        visited.insert(id.clone());
201	
202	        if let Some(m) = all_manifests.get(&id) {
203	            // Check conflicts with already-active skills.
204	            if let Some(conflict) = SkillDependencyGraph::check_conflicts(m, active_skill_ids) {
205	                return Err(SkillError::SkillConflict {
206	                    skill_id: id.clone(),
207	                    conflict,
208	                });
209	            }
210	            for dep in &m.depends {
211	                if !visited.contains(dep) {
212	                    stack.push(dep.clone());
213	                }
214	            }
215	            relevant.push(m.clone());
216	        }
217	        // Unknown dependency IDs are ignored here; the caller may choose to error.
218	    }
219	
220	    let g = SkillDependencyGraph::from_manifests(relevant.iter());
221	    let order = g.activation_order()?;
222	
223	    // Filter out already-active skills.
224	    let plan: Vec<String> = order
225	        .into_iter()
226	        .filter(|id| !active_skill_ids.contains(id))
227	        .collect();
228	
229	    Ok(plan)
230	}
