159	    /// Parse the manifest for a Cold skill, transitioning it to Warm.
160	    pub fn warm(&self, skill_id: &str) -> SkillResult<SkillManifest> {
161	        let mut skills = self.skills.write().expect("skills lock poisoned");
162	        let skill = skills
163	            .get_mut(skill_id)
164	            .ok_or_else(|| SkillError::NotFound {
165	                name: skill_id.into(),
166	            })?;
167	
168	        if skill.state != SkillState::Cold {
169	            return Err(SkillError::InvalidTransition {
170	                skill_id: skill_id.into(),
171	                from: skill.state.to_string(),
172	                to: "Warm".into(),
173	            });
174	        }
175	
176	        let manifest_path = self.skills_dir.join(skill_id).join("skill.json");
177	        let content = std::fs::read_to_string(&manifest_path).map_err(|e| SkillError::Io {
178	            skill_id: skill_id.into(),
179	            source: e,
180	        })?;
181	
182	        let manifest: SkillManifest =
183	            serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
184	                path: manifest_path.display().to_string(),
185	                message: e.to_string(),
186	            })?;
187	
188	        skill.manifest = manifest.clone();
189	        skill.state = SkillState::Warm;
190	
191	        Ok(manifest)
192	    }
