359	    /// Deactivate a Hot skill: mark inactive, free budget.
360	    /// Triples already in the KG persist until engine restart.
361	    pub fn deactivate(&self, skill_id: &str) -> SkillResult<()> {
362	        let mut skills = self.skills.write().expect("skills lock poisoned");
363	        let skill = skills
364	            .get_mut(skill_id)
365	            .ok_or_else(|| SkillError::NotFound {
366	                name: skill_id.into(),
367	            })?;
368	
369	        if skill.state != SkillState::Hot {
370	            return Err(SkillError::InvalidTransition {
371	                skill_id: skill_id.into(),
372	                from: skill.state.to_string(),
373	                to: "Warm (deactivate)".into(),
374	            });
375	        }
376	
377	        self.loaded_bytes
378	            .fetch_sub(skill.memory_bytes, Ordering::Relaxed);
379	        skill.state = SkillState::Warm;
380	        skill.memory_bytes = 0;
381	        skill.last_used_at = None;
382	
383	        self.rule_sources
384	            .write()
385	            .expect("rule_sources lock poisoned")
386	            .remove(skill_id);
387	
388	        // Phase 31b/c: clear per-skill data.
389	        self.skill_triples
390	            .write()
391	            .expect("skill_triples lock poisoned")
392	            .remove(skill_id);
393	        self.prototypes.remove(skill_id);
394	        self.last_used.remove(skill_id);
395	
396	        Ok(())
397	    }
