508	    /// Return the triples loaded from a specific skill (Phase 31b).
509	    ///
510	    /// Only populated for currently-Hot skills loaded via the numeric triple
511	    /// path. Label-based triples loaded through `engine.load_skill_with_labels`
512	    /// are not tracked here.
513	    pub fn triples_of_skill(&self, skill_id: &str) -> Vec<Triple> {
514	        self.skill_triples
515	            .read()
