522	    /// Compute and store a neural prototype HyperVec for a skill (Phase 31b).
523	    ///
524	    /// The prototype is the bundle of all symbol vectors for the skill's
525	    /// triples (subject, predicate, object). Stored as serialised bytes under
526	    /// the skill's ID; retrieve with `prototype_bytes`.
527	    ///
528	    /// Call this after `activate` for skills where semantic matching is needed.
529	    /// Returns `None` if the skill has no triples to bundle.
530	    pub fn compute_and_store_prototype(&self, skill_id: &str, ops: &VsaOps) -> Option<()> {
531	        let triples = self.triples_of_skill(skill_id);
532	        if triples.is_empty() {
533	            return None;
534	        }
535	
536	        // Encode each triple's symbols.
537	        let vecs: Vec<HyperVec> = triples
538	            .iter()
539	            .flat_map(|t| {
540	                [
541	                    encode_symbol(ops, t.subject),
542	                    encode_symbol(ops, t.predicate),
543	                    encode_symbol(ops, t.object),
544	                ]
545	            })
546	            .collect();
547	
548	        let refs: Vec<&HyperVec> = vecs.iter().collect();
549	        let prototype = ops.bundle(&refs).ok()?;
550	
551	        // Serialise to bytes for compact storage.
552	        let bytes = bincode::serialize(&prototype).ok()?;
553	        self.prototypes.insert(skill_id.to_string(), bytes);
554	        Some(())
555	    }
556	
557	    /// Retrieve the stored prototype bytes for a skill (Phase 31b).
558	    ///
559	    /// Returns `None` if no prototype has been computed for this skill.
560	    pub fn prototype_bytes(&self, skill_id: &str) -> Option<Vec<u8>> {
561	        self.prototypes.get(skill_id).map(|b| b.value().clone())
562	    }
563	
564	    /// Deserialise and return the prototype HyperVec for a skill (Phase 31b).
565	    ///
566	    /// Returns `None` if no prototype is stored for this skill.
567	    pub fn prototype(&self, skill_id: &str) -> Option<HyperVec> {
568	        let bytes = self.prototype_bytes(skill_id)?;
569	        bincode::deserialize(&bytes).ok()
570	    }
571	
572	    /// Find the `k` most similar skills to a query HyperVec (Phase 31b/c).
573	    ///
574	    /// Returns a list of `(skill_id, similarity)` pairs sorted by descending
575	    /// similarity. Only considers skills that have a stored prototype.
576	    pub fn match_skills_to_query(
577	        &self,
578	        query: &HyperVec,
579	        ops: &VsaOps,
580	        k: usize,
581	        threshold: f32,
582	    ) -> Vec<(String, f32)> {
583	        let mut matches: Vec<(String, f32)> = self
584	            .prototypes
585	            .iter()
586	            .filter_map(|entry| {
587	                let skill_id = entry.key().clone();
588	                let proto: HyperVec = bincode::deserialize(entry.value()).ok()?;
589	                let sim = ops.similarity(query, &proto).ok()?;
590	                if sim >= threshold {
591	                    Some((skill_id, sim))
592	                } else {
593	                    None
594	                }
595	            })
596	            .collect();
597	
598	        matches.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
599	        matches.truncate(k);
600	        matches
601	    }
