1	//! Dynamic skill synthesis: create skills from knowledge gaps.
2	//!
3	//! Phase 31e — when directed curiosity (Phase 11j) identifies a knowledge gap
4	//! that no existing skill covers, the synthesis pipeline:
5	//!   1. Ingests resources about the gap domain (web search, API).
6	//!   2. Consolidates the ingested triples.
7	//!   3. Uses Phase 30c's SkillAuthor to package the result as a new skill.
8	//!   4. Returns a `SkillCandidate` for user review before activation.
9	//!
10	//! This module provides the types and the orchestration stub; full execution
11	//! requires Phase 30c (LLM-assisted authoring) to be implemented.
12	
13	use serde::{Deserialize, Serialize};
14	
15	use crate::graph::Triple;
16	
17	use super::discover::SkillCandidate;
18	
19	/// A knowledge gap that motivated a synthesis attempt.
20	///
21	/// Typically produced by the directed curiosity module (Phase 11j).
22	#[derive(Debug, Clone, Serialize, Deserialize)]
23	pub struct SkillGap {
24	    /// Human-readable description of the gap.
25	    pub description: String,
26	    /// Domain tags associated with the gap.
27	    pub domain_tags: Vec<String>,
28	    /// Suggested skill name derived from the gap description.
29	    pub suggested_name: String,
30	    /// Concepts the agent tried to reason about but lacked knowledge for.
31	    pub missing_concepts: Vec<String>,
32	    /// Provenance token linking to the reasoning event that identified this gap.
33	    pub provenance_token: String,
34	}
35	
36	/// Resources gathered to fill a knowledge gap (output of the ingestion step).
37	#[derive(Debug, Clone)]
38	pub struct IngestedResources {
39	    /// Triples extracted from the gathered resources.
40	    pub triples: Vec<Triple>,
41	    /// Source URLs or identifiers for the gathered content.
42	    pub sources: Vec<String>,
43	    /// Number of raw bytes ingested.
44	    pub bytes_ingested: usize,
45	}
46	
47	/// Request to synthesize a skill.
48	#[derive(Debug, Clone, Serialize, Deserialize)]
49	pub struct SynthesisRequest {
50	    /// The knowledge gap that triggered this synthesis.
51	    pub gap: SkillGap,
52	    /// Maximum number of triples to include in the synthesized skill.
53	    pub max_triples: usize,
54	    /// Whether to require user approval before the candidate is promoted.
55	    pub require_approval: bool,
56	}
57	
58	impl Default for SynthesisRequest {
59	    fn default() -> Self {
60	        Self {
61	            gap: SkillGap {
62	                description: String::new(),
63	                domain_tags: Vec::new(),
64	                suggested_name: String::new(),
65	                missing_concepts: Vec::new(),
66	                provenance_token: String::new(),
67	            },
68	            max_triples: 500,
69	            require_approval: true,
70	        }
71	    }
72	}
73	
74	/// Outcome of a synthesis attempt.
75	#[derive(Debug, Clone)]
76	pub enum SynthesisResult {
77	    /// A candidate skill was produced and is pending user approval.
78	    Candidate(SkillCandidate),
79	    /// Synthesis was attempted but the gap was too narrow or resources were
80	    /// insufficient to build a coherent skill.
81	    InsufficientContent {
82	        gap_description: String,
83	        triples_found: usize,
84	        min_required: usize,
85	    },
86	    /// The gap is already covered by an existing skill (overlap detected).
87	    AlreadyCovered { covering_skill_id: String },
