1	//! Skill sharing protocol: export and import `.akhskill` archives.
2	//!
3	//! Phase 31f — skills are portable, self-contained archives (`.akhskill`,
4	//! a gzip-compressed tar) with an embedded `METADATA.json` carrying a CRC-32
5	//! integrity checksum. Recipes can reference remote URLs; the import path
6	//! validates and installs any archive.
7	//!
8	//! Archive layout:
9	//! ```text
10	//! my-skill.akhskill (tar.gz)
11	//! ├── METADATA.json     ← checksum + manifest summary
12	//! ├── skill.json        ← SkillManifest
13	//! ├── triples.json      ← triples (optional)
14	//! ├── rules.txt         ← rules (optional)
15	//! └── curriculum.json   ← curriculum (optional)
16	//! ```
17	
18	use std::io::{Read, Write};
19	use std::path::{Path, PathBuf};
20	
21	use flate2::Compression;
22	use flate2::Crc;
23	use flate2::read::GzDecoder;
24	use flate2::write::GzEncoder;
25	use serde::{Deserialize, Serialize};
26	
27	use crate::error::{SkillError, SkillResult};
28	
29	use super::SkillManifest;
30	
31	/// Metadata embedded in the `METADATA.json` file inside a `.akhskill` archive.
32	#[derive(Debug, Clone, Serialize, Deserialize)]
33	pub struct SkillArchiveMetadata {
34	    /// Archive format version (currently `1`).
35	    pub format_version: u32,
36	    /// Skill ID from the manifest.
37	    pub skill_id: String,
38	    /// Skill version from the manifest.
39	    pub skill_version: String,
40	    /// CRC-32 checksum of the raw `skill.json` content.
41	    pub manifest_checksum: u32,
42	    /// CRC-32 checksum of all content files concatenated (skill.json +
43	    /// triples.json + rules.txt + curriculum.json), in that order, skipping
44	    /// absent files.
45	    pub content_checksum: u32,
46	}
47	
48	/// Compute a CRC-32 checksum over a byte slice.
49	fn crc32(data: &[u8]) -> u32 {
50	    let mut crc = Crc::new();
51	    crc.update(data);
52	    crc.sum()
53	}
54	
55	/// Export a skill directory into a `.akhskill` archive at `output_path`.
56	///
57	/// Creates a gzip-compressed tar containing `METADATA.json`, `skill.json`,
58	/// and any optional content files present in the skill directory.
59	///
60	/// Returns the path to the created archive.
61	pub fn export_skill(skill_dir: &Path, output_path: &Path) -> SkillResult<PathBuf> {
62	    // ── Read skill.json ───────────────────────────────────────────────────
63	    let manifest_path = skill_dir.join("skill.json");
64	    let manifest_bytes = std::fs::read(&manifest_path).map_err(|e| SkillError::Io {
65	        skill_id: "<export>".into(),
66	        source: e,
67	    })?;
68	    let manifest: SkillManifest =
69	        serde_json::from_slice(&manifest_bytes).map_err(|e| SkillError::InvalidManifest {
70	            path: manifest_path.display().to_string(),
71	            message: e.to_string(),
72	        })?;
73	
74	    // ── Collect optional content files ────────────────────────────────────
75	    let optional_files: &[&str] = &["triples.json", "rules.txt", "curriculum.json"];
76	
77	    let mut content_crc = Crc::new();
78	    content_crc.update(&manifest_bytes);
79	
80	    let manifest_checksum = crc32(&manifest_bytes);
81	
82	    for &fname in optional_files {
83	        let fpath = skill_dir.join(fname);
84	        if fpath.exists() {
85	            let data = std::fs::read(&fpath).map_err(|e| SkillError::Io {
86	                skill_id: manifest.id.clone(),
87	                source: e,
88	            })?;
89	            content_crc.update(&data);
90	        }
91	    }
92	
93	    let content_checksum = content_crc.sum();
94	
95	    // ── Build METADATA.json ───────────────────────────────────────────────
96	    let metadata = SkillArchiveMetadata {
97	        format_version: 1,
98	        skill_id: manifest.id.clone(),
99	        skill_version: manifest.version.clone(),
100	        manifest_checksum,
101	        content_checksum,
102	    };
103	    let metadata_bytes =
104	        serde_json::to_vec_pretty(&metadata).map_err(|e| SkillError::ArchiveError {
105	            message: format!("metadata serialization failed: {e}"),
106	        })?;
107	
108	    // ── Write tar.gz archive ──────────────────────────────────────────────
109	    let output_file = std::fs::File::create(output_path).map_err(|e| SkillError::Io {
110	        skill_id: manifest.id.clone(),
111	        source: e,
112	    })?;
113	    let gz = GzEncoder::new(output_file, Compression::best());
114	    let mut builder = tar::Builder::new(gz);
115	
116	    // Append METADATA.json.
117	    append_bytes_as_file(&mut builder, "METADATA.json", &metadata_bytes, &manifest.id)?;
118	
119	    // Append skill.json.
120	    append_bytes_as_file(&mut builder, "skill.json", &manifest_bytes, &manifest.id)?;
121	
122	    // Append optional files.
123	    for &fname in optional_files {
124	        let fpath = skill_dir.join(fname);
125	        if fpath.exists() {
126	            let data = std::fs::read(&fpath).map_err(|e| SkillError::Io {
127	                skill_id: manifest.id.clone(),
128	                source: e,
129	            })?;
130	            append_bytes_as_file(&mut builder, fname, &data, &manifest.id)?;
131	        }
132	    }
133	
134	    let gz = builder.into_inner().map_err(|e| SkillError::ArchiveError {
135	        message: format!("tar finalize failed: {e}"),
136	    })?;
137	    gz.finish().map_err(|e| SkillError::ArchiveError {
138	        message: format!("gz finalize failed: {e}"),
139	    })?;
140	
141	    Ok(output_path.to_path_buf())
142	}
143	
144	/// Import a `.akhskill` archive into `skills_dir`.
145	///
146	/// Steps:
147	/// 1. Extract and parse `METADATA.json`.
148	/// 2. Recompute checksums and compare to the stored values.
149	/// 3. Extract all skill files to `skills_dir/{skill_id}/`.
150	/// 4. Return the installed skill ID.
151	pub fn import_skill(archive_path: &Path, skills_dir: &Path) -> SkillResult<String> {
152	    // ── Pass 1: read all entries into memory ──────────────────────────────
153	    let archive_file = std::fs::File::open(archive_path).map_err(|e| SkillError::Io {
154	        skill_id: "<import>".into(),
155	        source: e,
156	    })?;
157	    let gz = GzDecoder::new(archive_file);
158	    let mut archive = tar::Archive::new(gz);
159	
160	    let mut entries: std::collections::HashMap<String, Vec<u8>> = std::collections::HashMap::new();
161	
162	    for entry in archive.entries().map_err(|e| SkillError::ArchiveError {
163	        message: format!("reading archive entries: {e}"),
164	    })? {
165	        let mut entry = entry.map_err(|e| SkillError::ArchiveError {
166	            message: format!("reading entry: {e}"),
167	        })?;
168	        let path = entry
169	            .path()
170	            .map_err(|e| SkillError::ArchiveError {
171	                message: format!("entry path: {e}"),
172	            })?
173	            .to_string_lossy()
174	            .to_string();
175	        let mut data = Vec::new();
176	        entry.read_to_end(&mut data).map_err(|e| SkillError::Io {
177	            skill_id: "<import>".into(),
178	            source: e,
179	        })?;
180	        entries.insert(path, data);
181	    }
182	
183	    // ── Parse METADATA.json ───────────────────────────────────────────────
184	    let metadata_bytes = entries
185	        .get("METADATA.json")
186	        .ok_or_else(|| SkillError::ArchiveError {
187	            message: "archive missing METADATA.json".into(),
188	        })?;
189	    let metadata: SkillArchiveMetadata =
190	        serde_json::from_slice(metadata_bytes).map_err(|e| SkillError::ArchiveError {
191	            message: format!("METADATA.json parse error: {e}"),
192	        })?;
193	
194	    if metadata.format_version != 1 {
195	        return Err(SkillError::ArchiveError {
196	            message: format!(
197	                "unsupported archive format version {}; expected 1",
198	                metadata.format_version
199	            ),
200	        });
201	    }
202	
203	    // ── Parse and validate skill.json ─────────────────────────────────────
204	    let manifest_bytes = entries
205	        .get("skill.json")
206	        .ok_or_else(|| SkillError::ArchiveError {
207	            message: "archive missing skill.json".into(),
208	        })?;
209	
210	    let manifest_checksum = crc32(manifest_bytes);
211	    if manifest_checksum != metadata.manifest_checksum {
212	        return Err(SkillError::ChecksumMismatch {
213	            expected: metadata.manifest_checksum,
214	            actual: manifest_checksum,
215	        });
216	    }
217	
218	    let _manifest: SkillManifest =
219	        serde_json::from_slice(manifest_bytes).map_err(|e| SkillError::InvalidManifest {
220	            path: "skill.json (from archive)".into(),
221	            message: e.to_string(),
222	        })?;
223	
224	    // ── Verify content checksum ───────────────────────────────────────────
225	    let optional_files: &[&str] = &["triples.json", "rules.txt", "curriculum.json"];
226	    let mut content_crc = Crc::new();
227	    content_crc.update(manifest_bytes);
228	    for &fname in optional_files {
229	        if let Some(data) = entries.get(fname) {
230	            content_crc.update(data);
231	        }
232	    }
233	    let content_checksum = content_crc.sum();
234	    if content_checksum != metadata.content_checksum {
235	        return Err(SkillError::ChecksumMismatch {
236	            expected: metadata.content_checksum,
237	            actual: content_checksum,
238	        });
239	    }
240	
241	    // ── Install: write files to skills_dir/{skill_id}/ ───────────────────
242	    let skill_id = metadata.skill_id.clone();
243	    let dest_dir = skills_dir.join(&skill_id);
244	    std::fs::create_dir_all(&dest_dir).map_err(|e| SkillError::Io {
245	        skill_id: skill_id.clone(),
246	        source: e,
247	    })?;
248	
249	    for (fname, data) in &entries {
250	        if fname == "METADATA.json" {
251	            continue;
252	        }
253	        let dest = dest_dir.join(fname);
254	        std::fs::write(&dest, data).map_err(|e| SkillError::Io {
255	            skill_id: skill_id.clone(),
256	            source: e,
257	        })?;
258	    }
259	
260	    Ok(skill_id)
261	}
262	
263	/// Helper: append in-memory bytes as a file entry in a tar builder.
